insert into public.content_versions (item_id, version, payload) values ('a1-opp-hot', 1, '{"id":"a1-opp-hot","version":1,"level":"A1","primarySkill":"vocabulary","secondarySkills":[],"difficulty":1,"type":"multiple-choice","category":"antonym","prompt":"What is the opposite of ''hot''?","options":[{"id":"a","text":"cold"},{"id":"b","text":"big"},{"id":"c","text":"fast"},{"id":"d","text":"happy"}],"acceptedAnswers":["a"],"grading":{"mode":"option"},"explanation":{"en":"''Cold'' is the opposite of ''hot''.","he":"המילה ההפוכה ל-hot (חם) היא cold (קר)."},"tags":{"vocabulary":["hot","cold"],"grammar":[],"bagrut":[]},"modes":["word-battle","practice","placement","adventure"],"reviewStatus":"ai-drafted"}'::jsonb) on conflict (item_id, version) do nothing;
