insert into public.content_items (id, current_version, level, primary_skill, category, item_type, modes, tags, review_status, is_ranked_only) values ('a1-goes', 1, 'A1', 'grammar', 'sentence-completion', 'cloze', array['word-battle','grammar-race','practice','placement','adventure']::text[], '{"vocabulary":[],"grammar":["present-simple-3rd-person"],"bagrut":[]}'::jsonb, 'ai-drafted', false) on conflict (id) do update set current_version = excluded.current_version, level = excluded.level, tags = excluded.tags, review_status = excluded.review_status;
insert into public.content_versions (item_id, version, payload) values ('a1-goes', 1, '{"id":"a1-goes","version":1,"level":"A1","primarySkill":"grammar","secondarySkills":[],"difficulty":2,"type":"cloze","category":"sentence-completion","prompt":"She ___ to school every day.","options":[{"id":"a","text":"goes"},{"id":"b","text":"go","feedback":{"en":"With he, she or it we add -s or -es to the verb: she goes.","he":"עם he/she/it מוסיפים לפועל s או es: she goes."},"errorCategory":"subject-verb-agreement"},{"id":"c","text":"going","feedback":{"en":"''Going'' needs ''is'': She is going. For habits, use the Present Simple.","he":"going צריך is לפניו. להרגלים משתמשים בהווה פשוט."},"errorCategory":"tense"},{"id":"d","text":"gone","feedback":{"en":"''Gone'' is a past participle and needs ''has''.","he":"gone הוא צורת עבר שלישית וצריך has לפניו."},"errorCategory":"tense"}],"acceptedAnswers":["a"],"grading":{"mode":"option"},"explanation":{"en":"In the Present Simple, we add -s or -es to most verbs when the subject is he, she or it.","he":"בזמן Present Simple, כאשר נושא המשפט הוא he, she או it, בדרך כלל מוסיפים לפועל s או es."},"example":"He watches TV. She goes to school.","tags":{"vocabulary":[],"grammar":["present-simple-3rd-person"],"bagrut":[]},"modes":["word-battle","grammar-race","practice","placement","adventure"],"reviewStatus":"ai-drafted"}'::jsonb) on conflict (item_id, version) do nothing;
