insert into public.content_versions (item_id, version, payload) values ('a1-are-friends', 1, '{"id":"a1-are-friends","version":1,"level":"A1","primarySkill":"grammar","secondarySkills":[],"difficulty":1,"type":"cloze","category":"sentence-completion","prompt":"They ___ my friends.","options":[{"id":"a","text":"are"},{"id":"b","text":"is","feedback":{"en":"''Is'' goes with he, she or it. ''They'' needs ''are''.","he":"is הולך עם he/she/it. עם they משתמשים ב-are."},"errorCategory":"subject-verb-agreement"},{"id":"c","text":"am"},{"id":"d","text":"be"}],"acceptedAnswers":["a"],"grading":{"mode":"option"},"explanation":{"en":"The verb ''to be'' with ''they'' is ''are''.","he":"הפועל to be עם they הוא are."},"tags":{"vocabulary":[],"grammar":["verb-to-be"],"bagrut":[]},"modes":["word-battle","grammar-race","practice","placement","adventure"],"reviewStatus":"ai-drafted"}'::jsonb) on conflict (item_id, version) do nothing;
insert into public.content_items (id, current_version, level, primary_skill, category, item_type, modes, tags, review_status, is_ranked_only) values ('a1-an-apple', 1, 'A1', 'grammar', 'sentence-completion', 'cloze', array['word-battle','grammar-race','practice','placement','adventure']::text[], '{"vocabulary":[],"grammar":["articles-a-an"],"bagrut":[]}'::jsonb, 'ai-drafted', false) on conflict (id) do update set current_version = excluded.current_version, level = excluded.level, tags = excluded.tags, review_status = excluded.review_status;
insert into public.content_versions (item_id, version, payload) values ('a1-an-apple', 1, '{"id":"a1-an-apple","version":1,"level":"A1","primarySkill":"grammar","secondarySkills":[],"difficulty":2,"type":"cloze","category":"sentence-completion","prompt":"I have ___ apple.","options":[{"id":"a","text":"an"},{"id":"b","text":"a","feedback":{"en":"Before a vowel sound (a, e, i, o, u) we use ''an'', not ''a''.","he":"לפני צליל של תנועה (a, e, i, o, u) משתמשים ב-an ולא ב-a."},"errorCategory":"article"},{"id":"c","text":"two","feedback":{"en":"''Two'' needs a plural noun: two apples.","he":"two צריך שם עצם ברבים: two apples."},"errorCategory":"plural"},{"id":"d","text":"much","feedback":{"en":"''Much'' is used with uncountable nouns, not with ''apple''.","he":"much משמש עם שמות עצם שאינם ניתנים לספירה."},"errorCategory":"other"}],"acceptedAnswers":["a"],"grading":{"mode":"option"},"explanation":{"en":"''Apple'' starts with a vowel sound, so we use ''an''.","he":"apple מתחילה בצליל של תנועה, ולכן משתמשים ב-an."},"example":"an egg, an orange, a banana","tags":{"vocabulary":[],"grammar":["articles-a-an"],"bagrut":[]},"modes":["word-battle","grammar-race","practice","placement","adventure"],"reviewStatus":"ai-drafted"}'::jsonb) on conflict (item_id, version) do nothing;
