insert into public.content_versions (item_id, version, payload) values ('a1-in-may', 1, '{"id":"a1-in-may","version":1,"level":"A1","primarySkill":"grammar","secondarySkills":[],"difficulty":2,"type":"cloze","category":"sentence-completion","prompt":"My birthday is ___ May.","options":[{"id":"a","text":"in"},{"id":"b","text":"on","feedback":{"en":"''On'' is for days and dates: on Monday, on 5 May.","he":"on משמש לימים ותאריכים: on Monday."},"errorCategory":"preposition"},{"id":"c","text":"at","feedback":{"en":"''At'' is for clock times: at 7 o''clock.","he":"at משמש לשעות: at 7 o''clock."},"errorCategory":"preposition"},{"id":"d","text":"to"}],"acceptedAnswers":["a"],"grading":{"mode":"option"},"explanation":{"en":"We use ''in'' with months, years and seasons.","he":"משתמשים ב-in עם חודשים, שנים ועונות."},"example":"in May, in 2025, in summer","tags":{"vocabulary":[],"grammar":["prepositions-time"],"bagrut":[]},"modes":["word-battle","grammar-race","practice","placement","adventure"],"reviewStatus":"ai-drafted"}'::jsonb) on conflict (item_id, version) do nothing;
