insert into public.content_versions (item_id, version, payload) values ('a1-children', 1, '{"id":"a1-children","version":1,"level":"A1","primarySkill":"grammar","secondarySkills":[],"difficulty":3,"type":"cloze","category":"sentence-completion","prompt":"Two ___ are playing in the garden.","options":[{"id":"a","text":"children"},{"id":"b","text":"child","feedback":{"en":"After \"two\" we need a plural noun.","he":"אחרי two צריך שם עצם ברבים."},"errorCategory":"plural"},{"id":"c","text":"childs","feedback":{"en":"''Child'' has an irregular plural: children.","he":"לרבים של child יש צורה לא סדירה: children."},"errorCategory":"plural"},{"id":"d","text":"childrens","feedback":{"en":"''Children'' is already plural; don''t add -s.","he":"children כבר ברבים, לא מוסיפים s."},"errorCategory":"plural"}],"acceptedAnswers":["a"],"grading":{"mode":"option"},"explanation":{"en":"The plural of ''child'' is ''children''.","he":"הרבים של child הוא children."},"tags":{"vocabulary":[],"grammar":["irregular-plurals"],"bagrut":[]},"modes":["word-battle","grammar-race","practice","placement","adventure"],"reviewStatus":"ai-drafted"}'::jsonb) on conflict (item_id, version) do nothing;
