insert into public.content_versions (item_id, version, payload) values ('a1-his-bag', 1, '{"id":"a1-his-bag","version":1,"level":"A1","primarySkill":"grammar","secondarySkills":[],"difficulty":2,"type":"cloze","category":"sentence-completion","prompt":"This is Tom. ___ bag is blue.","options":[{"id":"a","text":"His"},{"id":"b","text":"Her","feedback":{"en":"''Her'' is for a woman or girl. Tom is a man.","he":"her משמש לאישה או לנערה. Tom הוא גבר."},"errorCategory":"pronoun"},{"id":"c","text":"Their","feedback":{"en":"''Their'' is for more than one person.","he":"their משמש ליותר מאדם אחד."},"errorCategory":"pronoun"},{"id":"d","text":"Its","feedback":{"en":"''Its'' is for animals and things, not people.","he":"its משמש לבעלי חיים ולחפצים."},"errorCategory":"pronoun"}],"acceptedAnswers":["a"],"grading":{"mode":"option"},"explanation":{"en":"''His'' shows that something belongs to a man or boy.","he":"his מראה שמשהו שייך לגבר או לנער."},"tags":{"vocabulary":[],"grammar":["possessive-adjectives"],"bagrut":[]},"modes":["word-battle","grammar-race","practice","placement","adventure"],"reviewStatus":"ai-drafted"}'::jsonb) on conflict (item_id, version) do nothing;
