insert into public.content_versions (item_id, version, payload) values ('a1-is-sleeping', 1, '{"id":"a1-is-sleeping","version":1,"level":"A1","primarySkill":"grammar","secondarySkills":[],"difficulty":3,"type":"cloze","category":"sentence-completion","prompt":"Look! The baby ___.","options":[{"id":"a","text":"is sleeping"},{"id":"b","text":"sleeps","feedback":{"en":"''Look!'' shows it is happening now, so we use the Present Progressive.","he":"Look! מראה שזה קורה עכשיו, לכן משתמשים ב-Present Progressive."},"errorCategory":"tense"},{"id":"c","text":"sleep"},{"id":"d","text":"sleeping","feedback":{"en":"We need ''is'' before ''sleeping''.","he":"צריך is לפני sleeping."},"errorCategory":"tense"}],"acceptedAnswers":["a"],"grading":{"mode":"option"},"explanation":{"en":"For actions happening right now, use am/is/are + verb-ing.","he":"לפעולות שקורות עכשיו משתמשים ב-am/is/are + פועל עם ing."},"tags":{"vocabulary":[],"grammar":["present-progressive"],"bagrut":[]},"modes":["word-battle","grammar-race","practice","placement","adventure"],"reviewStatus":"ai-drafted"}'::jsonb) on conflict (item_id, version) do nothing;
