insert into public.content_versions (item_id, version, payload) values ('a1-can-fly', 1, '{"id":"a1-can-fly","version":1,"level":"A1","primarySkill":"grammar","secondarySkills":[],"difficulty":2,"type":"cloze","category":"sentence-completion","prompt":"Birds ___ fly.","options":[{"id":"a","text":"can"},{"id":"b","text":"can to","feedback":{"en":"After ''can'' we use the base verb without ''to''.","he":"אחרי can בא הפועל בצורת הבסיס, בלי to."},"errorCategory":"modal"},{"id":"c","text":"cans","feedback":{"en":"''Can'' never takes -s.","he":"ל-can אף פעם לא מוסיפים s."},"errorCategory":"modal"},{"id":"d","text":"are can"}],"acceptedAnswers":["a"],"grading":{"mode":"option"},"explanation":{"en":"''Can'' + base verb expresses ability: Birds can fly.","he":"can + פועל בסיס מבטא יכולת."},"tags":{"vocabulary":[],"grammar":["modal-can"],"bagrut":[]},"modes":["word-battle","grammar-race","practice","placement","adventure"],"reviewStatus":"ai-drafted"}'::jsonb) on conflict (item_id, version) do nothing;
insert into public.content_items (id, current_version, level, primary_skill, category, item_type, modes, tags, review_status, is_ranked_only) values ('a1-there-are', 1, 'A1', 'grammar', 'sentence-completion', 'cloze', array['word-battle','grammar-race','practice','placement','adventure']::text[], '{"vocabulary":[],"grammar":["there-is-are"],"bagrut":[]}'::jsonb, 'ai-drafted', false) on conflict (id) do update set current_version = excluded.current_version, level = excluded.level, tags = excluded.tags, review_status = excluded.review_status;
insert into public.content_versions (item_id, version, payload) values ('a1-there-are', 1, '{"id":"a1-there-are","version":1,"level":"A1","primarySkill":"grammar","secondarySkills":[],"difficulty":2,"type":"cloze","category":"sentence-completion","prompt":"There ___ three books on the table.","options":[{"id":"a","text":"are"},{"id":"b","text":"is","feedback":{"en":"''There is'' is for one thing. Three books need ''there are''.","he":"there is משמש לדבר אחד. לשלושה ספרים צריך there are."},"errorCategory":"subject-verb-agreement"},{"id":"c","text":"be"},{"id":"d","text":"am"}],"acceptedAnswers":["a"],"grading":{"mode":"option"},"explanation":{"en":"Use ''there are'' with plural nouns.","he":"משתמשים ב-there are עם שמות עצם ברבים."},"tags":{"vocabulary":[],"grammar":["there-is-are"],"bagrut":[]},"modes":["word-battle","grammar-race","practice","placement","adventure"],"reviewStatus":"ai-drafted"}'::jsonb) on conflict (item_id, version) do nothing;
insert into public.content_items (id, current_version, level, primary_skill, category, item_type, modes, tags, review_status, is_ranked_only) values ('a1-so-hungry', 1, 'A1', 'grammar', 'connector', 'cloze', array['word-battle','grammar-race','practice','placement','adventure']::text[], '{"vocabulary":["so"],"grammar":["connectors-result"],"bagrut":[]}'::jsonb, 'ai-drafted', false) on conflict (id) do update set current_version = excluded.current_version, level = excluded.level, tags = excluded.tags, review_status = excluded.review_status;
insert into public.content_versions (item_id, version, payload) values ('a1-so-hungry', 1, '{"id":"a1-so-hungry","version":1,"level":"A1","primarySkill":"grammar","secondarySkills":[],"difficulty":2,"type":"cloze","category":"connector","prompt":"I''m hungry, ___ I''m making a sandwich.","options":[{"id":"a","text":"so"},{"id":"b","text":"but","feedback":{"en":"''But'' shows contrast. Making a sandwich is a result of being hungry.","he":"but מבטא ניגוד, אבל הכנת כריך היא תוצאה של רעב."},"errorCategory":"connector-logic"},{"id":"c","text":"because","feedback":{"en":"''Because'' gives a reason. Here the second part is a result.","he":"because נותן סיבה, וכאן החלק השני הוא תוצאה."},"errorCategory":"connector-logic"},{"id":"d","text":"or"}],"acceptedAnswers":["a"],"grading":{"mode":"option"},"explanation":{"en":"''So'' introduces a result.","he":"so מציג תוצאה."},"tags":{"vocabulary":["so"],"grammar":["connectors-result"],"bagrut":[]},"modes":["word-battle","grammar-race","practice","placement","adventure"],"reviewStatus":"ai-drafted"}'::jsonb) on conflict (item_id, version) do nothing;
