insert into public.content_versions (item_id, version, payload) values ('a1-pets', 1, '{"id":"a1-pets","version":1,"level":"A1","primarySkill":"reading","secondarySkills":[],"difficulty":2,"type":"multiple-choice","category":"reading-inference","prompt":"How many pets does Ben have?","context":"Ben has a cat and a dog. He doesn''t have a bird.","options":[{"id":"a","text":"two"},{"id":"b","text":"one"},{"id":"c","text":"three"},{"id":"d","text":"four"}],"acceptedAnswers":["a"],"grading":{"mode":"option"},"explanation":{"en":"Ben has a cat and a dog — that is two pets. He does not have a bird.","he":"לבן יש חתול וכלב — שתי חיות מחמד. אין לו ציפור."},"tags":{"vocabulary":["pet"],"grammar":[],"bagrut":[]},"modes":["word-battle","practice","placement","adventure","english-detective"],"reviewStatus":"ai-drafted"}'::jsonb) on conflict (item_id, version) do nothing;
