insert into public.content_items (id, current_version, level, primary_skill, category, item_type, modes, tags, review_status, is_ranked_only) values ('a1-doesnt-like', 1, 'A1', 'grammar', 'sentence-completion', 'cloze', array['word-battle','grammar-race','practice','placement','adventure']::text[], '{"vocabulary":[],"grammar":["present-simple-negative"],"bagrut":[]}'::jsonb, 'ai-drafted', false) on conflict (id) do update set current_version = excluded.current_version, level = excluded.level, tags = excluded.tags, review_status = excluded.review_status;
insert into public.content_versions (item_id, version, payload) values ('a1-doesnt-like', 1, '{"id":"a1-doesnt-like","version":1,"level":"A1","primarySkill":"grammar","secondarySkills":[],"difficulty":3,"type":"cloze","category":"sentence-completion","prompt":"He ___ like fish.","options":[{"id":"a","text":"doesn''t"},{"id":"b","text":"don''t","feedback":{"en":"With he, she or it, the negative is ''doesn''t''.","he":"עם he/she/it השלילה היא doesn''t."},"errorCategory":"subject-verb-agreement"},{"id":"c","text":"isn''t","feedback":{"en":"''Isn''t'' is used with adjectives or -ing verbs, not with ''like''.","he":"isn''t לא משמש לשלילה של פועל כמו like."},"errorCategory":"tense"},{"id":"d","text":"not"}],"acceptedAnswers":["a"],"grading":{"mode":"option"},"explanation":{"en":"Present Simple negative with he/she/it: doesn''t + base verb.","he":"שלילה בהווה פשוט עם he/she/it: doesn''t + פועל בסיס."},"tags":{"vocabulary":[],"grammar":["present-simple-negative"],"bagrut":[]},"modes":["word-battle","grammar-race","practice","placement","adventure"],"reviewStatus":"ai-drafted"}'::jsonb) on conflict (item_id, version) do nothing;
insert into public.content_items (id, current_version, level, primary_skill, category, item_type, modes, tags, review_status, is_ranked_only) values ('a2-went', 1, 'A2', 'grammar', 'sentence-completion', 'cloze', array['word-battle','grammar-race','practice','placement','adventure']::text[], '{"vocabulary":[],"grammar":["past-simple-irregular"],"bagrut":[]}'::jsonb, 'ai-drafted', false) on conflict (id) do update set current_version = excluded.current_version, level = excluded.level, tags = excluded.tags, review_status = excluded.review_status;
insert into public.content_versions (item_id, version, payload) values ('a2-went', 1, '{"id":"a2-went","version":1,"level":"A2","primarySkill":"grammar","secondarySkills":[],"difficulty":2,"type":"cloze","category":"sentence-completion","prompt":"Yesterday we ___ to the beach.","options":[{"id":"a","text":"went"},{"id":"b","text":"go","feedback":{"en":"''Yesterday'' tells us we need the past.","he":"yesterday מראה שצריך זמן עבר."},"errorCategory":"tense"},{"id":"c","text":"goes"},{"id":"d","text":"have gone","feedback":{"en":"We don''t use the Present Perfect with a finished time like ''yesterday''.","he":"לא משתמשים ב-Present Perfect עם זמן שהסתיים כמו yesterday."},"errorCategory":"tense"}],"acceptedAnswers":["a"],"grading":{"mode":"option"},"explanation":{"en":"''Go'' is irregular: its past form is ''went''.","he":"go הוא פועל לא סדיר: צורת העבר שלו היא went."},"tags":{"vocabulary":[],"grammar":["past-simple-irregular"],"bagrut":[]},"modes":["word-battle","grammar-race","practice","placement","adventure"],"reviewStatus":"ai-drafted"}'::jsonb) on conflict (item_id, version) do nothing;
insert into public.content_items (id, current_version, level, primary_skill, category, item_type, modes, tags, review_status, is_ranked_only) values ('a2-didnt-send', 1, 'A2', 'grammar', 'sentence-completion', 'cloze', array['word-battle','grammar-race','practice','placement','adventure']::text[], '{"vocabulary":[],"grammar":["past-simple-negative"],"bagrut":[]}'::jsonb, 'ai-drafted', false) on conflict (id) do update set current_version = excluded.current_version, level = excluded.level, tags = excluded.tags, review_status = excluded.review_status;
insert into public.content_versions (item_id, version, payload) values ('a2-didnt-send', 1, '{"id":"a2-didnt-send","version":1,"level":"A2","primarySkill":"grammar","secondarySkills":[],"difficulty":2,"type":"cloze","category":"sentence-completion","prompt":"She didn''t ___ the email.","options":[{"id":"a","text":"send"},{"id":"b","text":"sent","feedback":{"en":"After ''didn''t'' we use the base verb.","he":"אחרי didn''t בא הפועל בצורת הבסיס."},"errorCategory":"tense"},{"id":"c","text":"sends"},{"id":"d","text":"sending"}],"acceptedAnswers":["a"],"grading":{"mode":"option"},"explanation":{"en":"In the past negative, ''didn''t'' already shows the past, so the verb stays in its base form.","he":"בשלילה בעבר, didn''t כבר מראה עבר, ולכן הפועל נשאר בצורת הבסיס."},"tags":{"vocabulary":[],"grammar":["past-simple-negative"],"bagrut":[]},"modes":["word-battle","grammar-race","practice","placement","adventure"],"reviewStatus":"ai-drafted"}'::jsonb) on conflict (item_id, version) do nothing;
insert into public.content_items (id, current_version, level, primary_skill, category, item_type, modes, tags, review_status, is_ranked_only) values ('a2-taller', 1, 'A2', 'grammar', 'sentence-completion', 'cloze', array['word-battle','grammar-race','practice','placement','adventure']::text[], '{"vocabulary":[],"grammar":["comparatives"],"bagrut":[]}'::jsonb, 'ai-drafted', false) on conflict (id) do update set current_version = excluded.current_version, level = excluded.level, tags = excluded.tags, review_status = excluded.review_status;
insert into public.content_versions (item_id, version, payload) values ('a2-taller', 1, '{"id":"a2-taller","version":1,"level":"A2","primarySkill":"grammar","secondarySkills":[],"difficulty":2,"type":"cloze","category":"sentence-completion","prompt":"My brother is ___ than me.","options":[{"id":"a","text":"taller"},{"id":"b","text":"more tall","feedback":{"en":"Short adjectives take -er, not ''more''.","he":"לתארים קצרים מוסיפים er ולא more."},"errorCategory":"comparison"},{"id":"c","text":"tallest","feedback":{"en":"''Tallest'' compares three or more; ''than'' needs the comparative.","he":"tallest משווה שלושה ומעלה; than דורש צורת השוואה."},"errorCategory":"comparison"},{"id":"d","text":"tall"}],"acceptedAnswers":["a"],"grading":{"mode":"option"},"explanation":{"en":"Comparative of short adjectives: adjective + -er + than.","he":"השוואה של תארים קצרים: תואר + er + than."},"tags":{"vocabulary":[],"grammar":["comparatives"],"bagrut":[]},"modes":["word-battle","grammar-race","practice","placement","adventure"],"reviewStatus":"ai-drafted"}'::jsonb) on conflict (item_id, version) do nothing;
insert into public.content_items (id, current_version, level, primary_skill, category, item_type, modes, tags, review_status, is_ranked_only) values ('a2-best-film', 1, 'A2', 'grammar', 'sentence-completion', 'cloze', array['word-battle','grammar-race','practice','placement','adventure']::text[], '{"vocabulary":[],"grammar":["superlatives"],"bagrut":[]}'::jsonb, 'ai-drafted', false) on conflict (id) do update set current_version = excluded.current_version, level = excluded.level, tags = excluded.tags, review_status = excluded.review_status;
insert into public.content_versions (item_id, version, payload) values ('a2-best-film', 1, '{"id":"a2-best-film","version":1,"level":"A2","primarySkill":"grammar","secondarySkills":[],"difficulty":3,"type":"cloze","category":"sentence-completion","prompt":"This is the ___ film I have ever seen.","options":[{"id":"a","text":"best"},{"id":"b","text":"better","feedback":{"en":"''Better'' compares two things. ''The ... ever'' needs the superlative.","he":"better משווה בין שניים. the ... ever דורש דרגה עליונה."},"errorCategory":"comparison"},{"id":"c","text":"good"},{"id":"d","text":"most good","feedback":{"en":"''Good'' is irregular: good – better – best.","he":"good לא סדיר: good – better – best."},"errorCategory":"comparison"}],"acceptedAnswers":["a"],"grading":{"mode":"option"},"explanation":{"en":"The superlative of ''good'' is ''the best''.","he":"הדרגה העליונה של good היא the best."},"tags":{"vocabulary":[],"grammar":["superlatives"],"bagrut":[]},"modes":["word-battle","grammar-race","practice","placement","adventure"],"reviewStatus":"ai-drafted"}'::jsonb) on conflict (item_id, version) do nothing;
insert into public.content_items (id, current_version, level, primary_skill, category, item_type, modes, tags, review_status, is_ranked_only) values ('a2-how-much-water', 1, 'A2', 'grammar', 'sentence-completion', 'cloze', array['word-battle','grammar-race','practice','placement','adventure']::text[], '{"vocabulary":[],"grammar":["countable-uncountable"],"bagrut":[]}'::jsonb, 'ai-drafted', false) on conflict (id) do update set current_version = excluded.current_version, level = excluded.level, tags = excluded.tags, review_status = excluded.review_status;
insert into public.content_versions (item_id, version, payload) values ('a2-how-much-water', 1, '{"id":"a2-how-much-water","version":1,"level":"A2","primarySkill":"grammar","secondarySkills":[],"difficulty":2,"type":"cloze","category":"sentence-completion","prompt":"How ___ water do you drink every day?","options":[{"id":"a","text":"much"},{"id":"b","text":"many","feedback":{"en":"''Many'' is for countable nouns. Water is uncountable.","he":"many משמש לשמות עצם ניתנים לספירה. מים אינם ניתנים לספירה."},"errorCategory":"plural"},{"id":"c","text":"a lot"},{"id":"d","text":"few"}],"acceptedAnswers":["a"],"grading":{"mode":"option"},"explanation":{"en":"Use ''how much'' with uncountable nouns like water, money and time.","he":"משתמשים ב-how much עם שמות עצם שאינם ניתנים לספירה, כמו water, money, time."},"tags":{"vocabulary":[],"grammar":["countable-uncountable"],"bagrut":[]},"modes":["word-battle","grammar-race","practice","placement","adventure"],"reviewStatus":"ai-drafted"}'::jsonb) on conflict (item_id, version) do nothing;
