insert into public.content_versions (item_id, version, payload) values ('a2-going-to-rain', 1, '{"id":"a2-going-to-rain","version":1,"level":"A2","primarySkill":"grammar","secondarySkills":[],"difficulty":3,"type":"cloze","category":"sentence-completion","prompt":"Look at those dark clouds. It ___ rain.","options":[{"id":"a","text":"is going to"},{"id":"b","text":"going to","feedback":{"en":"We need ''is'' before ''going to''.","he":"צריך is לפני going to."},"errorCategory":"tense"},{"id":"c","text":"will to"},{"id":"d","text":"is go to"}],"acceptedAnswers":["a"],"grading":{"mode":"option"},"explanation":{"en":"Use ''be going to'' for predictions based on what we can see now.","he":"משתמשים ב-be going to לתחזית שמבוססת על מה שרואים עכשיו."},"tags":{"vocabulary":[],"grammar":["future-going-to"],"bagrut":[]},"modes":["word-battle","grammar-race","practice","placement","adventure"],"reviewStatus":"ai-drafted"}'::jsonb) on conflict (item_id, version) do nothing;
