insert into public.content_versions (item_id, version, payload) values ('a2-take-off', 1, '{"id":"a2-take-off","version":1,"level":"A2","primarySkill":"vocabulary","secondarySkills":[],"difficulty":2,"type":"cloze","category":"phrasal-verb","prompt":"Please ___ your shoes before you come in.","options":[{"id":"a","text":"take off"},{"id":"b","text":"take on","feedback":{"en":"''Take on'' means to accept work or responsibility.","he":"take on פירושו לקבל על עצמך עבודה או אחריות."},"errorCategory":"phrasal-verb"},{"id":"c","text":"take up"},{"id":"d","text":"take after","feedback":{"en":"''Take after'' means to look or act like a family member.","he":"take after פירושו להיות דומה לבן משפחה."},"errorCategory":"phrasal-verb"}],"acceptedAnswers":["a"],"grading":{"mode":"option"},"explanation":{"en":"''Take off'' clothes or shoes = remove them.","he":"take off בגדים או נעליים = להוריד אותם."},"tags":{"vocabulary":["take off"],"grammar":[],"bagrut":[]},"modes":["word-battle","practice","placement","adventure"],"reviewStatus":"ai-drafted"}'::jsonb) on conflict (item_id, version) do nothing;
