insert into public.content_versions (item_id, version, payload) values ('a2-because-rain', 1, '{"id":"a2-because-rain","version":1,"level":"A2","primarySkill":"grammar","secondarySkills":[],"difficulty":2,"type":"cloze","category":"connector","prompt":"We stayed at home ___ it was raining.","options":[{"id":"a","text":"because"},{"id":"b","text":"so","feedback":{"en":"''So'' introduces a result, but the rain is the reason.","he":"so מציג תוצאה, אבל הגשם הוא הסיבה."},"errorCategory":"connector-logic"},{"id":"c","text":"but"},{"id":"d","text":"although","feedback":{"en":"''Although'' shows contrast; staying home is not surprising when it rains.","he":"although מבטא ניגוד, אבל להישאר בבית כשיורד גשם אינו מפתיע."},"errorCategory":"connector-logic"}],"acceptedAnswers":["a"],"grading":{"mode":"option"},"explanation":{"en":"''Because'' introduces a reason.","he":"because מציג סיבה."},"tags":{"vocabulary":["because"],"grammar":["connectors-reason"],"bagrut":[]},"modes":["word-battle","grammar-race","practice","placement","adventure"],"reviewStatus":"ai-drafted"}'::jsonb) on conflict (item_id, version) do nothing;
