insert into public.content_items (id, current_version, level, primary_skill, category, item_type, modes, tags, review_status, is_ranked_only) values ('a2-help-me', 1, 'A2', 'grammar', 'sentence-completion', 'cloze', array['word-battle','grammar-race','practice','placement','adventure']::text[], '{"vocabulary":[],"grammar":["object-pronouns"],"bagrut":[]}'::jsonb, 'ai-drafted', false) on conflict (id) do update set current_version = excluded.current_version, level = excluded.level, tags = excluded.tags, review_status = excluded.review_status;
insert into public.content_versions (item_id, version, payload) values ('a2-help-me', 1, '{"id":"a2-help-me","version":1,"level":"A2","primarySkill":"grammar","secondarySkills":[],"difficulty":2,"type":"cloze","category":"sentence-completion","prompt":"Can you help ___?","options":[{"id":"a","text":"me"},{"id":"b","text":"I","feedback":{"en":"''I'' is a subject pronoun. After a verb we need the object pronoun ''me''.","he":"I הוא כינוי נושא. אחרי פועל צריך כינוי מושא: me."},"errorCategory":"pronoun"},{"id":"c","text":"my"},{"id":"d","text":"mine"}],"acceptedAnswers":["a"],"grading":{"mode":"option"},"explanation":{"en":"After a verb or preposition, use an object pronoun: me, you, him, her, us, them.","he":"אחרי פועל או מילת יחס משתמשים בכינוי מושא: me, you, him, her, us, them."},"tags":{"vocabulary":[],"grammar":["object-pronouns"],"bagrut":[]},"modes":["word-battle","grammar-race","practice","placement","adventure"],"reviewStatus":"ai-drafted"}'::jsonb) on conflict (item_id, version) do nothing;
