insert into public.content_versions (item_id, version, payload) values ('a2-always-late', 1, '{"id":"a2-always-late","version":1,"level":"A2","primarySkill":"grammar","secondarySkills":[],"difficulty":3,"type":"error-correction","category":"grammar-correction","prompt":"Which sentence is correct?","options":[{"id":"a","text":"She is always late."},{"id":"b","text":"She always is late.","feedback":{"en":"Adverbs of frequency go after the verb ''to be''.","he":"תארי פועל של תדירות באים אחרי הפועל to be."},"errorCategory":"word-order"},{"id":"c","text":"Always she is late."},{"id":"d","text":"She is late always."}],"acceptedAnswers":["a"],"grading":{"mode":"option"},"explanation":{"en":"Adverbs of frequency (always, never, often) go after ''to be'' but before other verbs: She is always late. She always walks.","he":"תארי תדירות (always, never, often) באים אחרי to be, אבל לפני פעלים אחרים."},"tags":{"vocabulary":[],"grammar":["adverbs-of-frequency"],"bagrut":[]},"modes":["word-battle","grammar-race","practice","placement","adventure"],"reviewStatus":"ai-drafted"}'::jsonb) on conflict (item_id, version) do nothing;
