insert into public.content_versions (item_id, version, payload) values ('a2-was-watching', 1, '{"id":"a2-was-watching","version":1,"level":"A2","primarySkill":"grammar","secondarySkills":[],"difficulty":3,"type":"cloze","category":"sentence-completion","prompt":"I ___ TV when the phone rang.","options":[{"id":"a","text":"was watching"},{"id":"b","text":"watched","feedback":{"en":"The longer action in progress uses the Past Progressive.","he":"לפעולה ארוכה שהייתה בתהליך משתמשים ב-Past Progressive."},"errorCategory":"tense"},{"id":"c","text":"am watching"},{"id":"d","text":"were watching","feedback":{"en":"With ''I'' we use ''was'', not ''were''.","he":"עם I משתמשים ב-was ולא ב-were."},"errorCategory":"subject-verb-agreement"}],"acceptedAnswers":["a"],"grading":{"mode":"option"},"explanation":{"en":"Past Progressive (was/were + -ing) for an action in progress; Past Simple for the short action that interrupted it.","he":"Past Progressive לפעולה שהייתה בתהליך; Past Simple לפעולה הקצרה שקטעה אותה."},"tags":{"vocabulary":[],"grammar":["past-progressive"],"bagrut":[]},"modes":["word-battle","grammar-race","practice","placement","adventure"],"reviewStatus":"ai-drafted"}'::jsonb) on conflict (item_id, version) do nothing;
