insert into public.content_versions (item_id, version, payload) values ('a2-maya-cafe', 1, '{"id":"a2-maya-cafe","version":1,"level":"A2","primarySkill":"reading","secondarySkills":[],"difficulty":3,"type":"multiple-choice","category":"reading-inference","prompt":"Why did Maya start working at the café?","context":"Maya wanted to buy a new phone, but she only had half the money. So she started working at a café on weekends.","options":[{"id":"a","text":"To get money for a phone"},{"id":"b","text":"Because she loves coffee"},{"id":"c","text":"Because her phone was broken"},{"id":"d","text":"To meet new friends"}],"acceptedAnswers":["a"],"grading":{"mode":"option"},"explanation":{"en":"She didn''t have enough money for the phone, so she started working. ''So'' links the reason and the result.","he":"לא היה לה מספיק כסף לטלפון, ולכן התחילה לעבוד. so מקשר בין סיבה לתוצאה."},"tags":{"vocabulary":["half"],"grammar":[],"bagrut":[]},"modes":["word-battle","practice","placement","adventure","english-detective"],"reviewStatus":"ai-drafted"}'::jsonb) on conflict (item_id, version) do nothing;
