insert into public.content_versions (item_id, version, payload) values ('b1-lived-since', 1, '{"id":"b1-lived-since","version":1,"level":"B1","primarySkill":"grammar","secondarySkills":[],"difficulty":2,"type":"cloze","category":"sentence-completion","prompt":"I ___ in Tel Aviv since 2019.","options":[{"id":"a","text":"have lived"},{"id":"b","text":"lived","feedback":{"en":"''Since 2019'' connects the past to now, so we need the Present Perfect.","he":"since 2019 מחבר בין העבר להווה, ולכן צריך Present Perfect."},"errorCategory":"tense"},{"id":"c","text":"am living","feedback":{"en":"With ''since'' + a starting point, use the Present Perfect, not the Present Progressive.","he":"עם since ונקודת התחלה משתמשים ב-Present Perfect."},"errorCategory":"tense"},{"id":"d","text":"live"}],"acceptedAnswers":["a"],"grading":{"mode":"option"},"explanation":{"en":"Present Perfect (have/has + past participle) for situations that started in the past and continue now, often with ''since'' or ''for''.","he":"Present Perfect משמש למצב שהתחיל בעבר ונמשך עד היום, לרוב עם since או for."},"example":"She has worked here for five years.","tags":{"vocabulary":[],"grammar":["present-perfect-since-for"],"bagrut":[]},"modes":["word-battle","grammar-race","practice","placement","adventure"],"reviewStatus":"ai-drafted"}'::jsonb) on conflict (item_id, version) do nothing;
