insert into public.content_versions (item_id, version, payload) values ('b1-lost-yesterday', 1, '{"id":"b1-lost-yesterday","version":1,"level":"B1","primarySkill":"grammar","secondarySkills":[],"difficulty":2,"type":"cloze","category":"sentence-completion","prompt":"She ___ her keys yesterday.","options":[{"id":"a","text":"lost"},{"id":"b","text":"has lost","feedback":{"en":"''Yesterday'' is a finished time, so use the Past Simple.","he":"yesterday הוא זמן שהסתיים, לכן משתמשים ב-Past Simple."},"errorCategory":"tense"},{"id":"c","text":"loses"},{"id":"d","text":"has losed"}],"acceptedAnswers":["a"],"grading":{"mode":"option"},"explanation":{"en":"Use the Past Simple with finished time expressions such as yesterday, last week, in 2010.","he":"משתמשים ב-Past Simple עם ביטויי זמן שהסתיימו: yesterday, last week, in 2010."},"tags":{"vocabulary":[],"grammar":["past-simple-vs-present-perfect"],"bagrut":[]},"modes":["word-battle","grammar-race","practice","placement","adventure"],"reviewStatus":"ai-drafted"}'::jsonb) on conflict (item_id, version) do nothing;
