insert into public.content_versions (item_id, version, payload) values ('b1-will-cancel', 1, '{"id":"b1-will-cancel","version":1,"level":"B1","primarySkill":"grammar","secondarySkills":[],"difficulty":2,"type":"cloze","category":"sentence-completion","prompt":"If it rains tomorrow, we ___ the trip.","options":[{"id":"a","text":"will cancel"},{"id":"b","text":"would cancel","feedback":{"en":"''Would'' is for imaginary situations (second conditional). Rain tomorrow is a real possibility.","he":"would משמש למצבים דמיוניים. גשם מחר הוא אפשרות אמיתית."},"errorCategory":"conditional"},{"id":"c","text":"cancelled"},{"id":"d","text":"had cancelled"}],"acceptedAnswers":["a"],"grading":{"mode":"option"},"explanation":{"en":"First conditional: If + Present Simple, will + base verb — for real future possibilities.","he":"משפט תנאי ראשון: If + הווה פשוט, will + פועל בסיס — לאפשרויות אמיתיות בעתיד."},"tags":{"vocabulary":[],"grammar":["first-conditional"],"bagrut":[]},"modes":["word-battle","grammar-race","practice","placement","adventure"],"reviewStatus":"ai-drafted"}'::jsonb) on conflict (item_id, version) do nothing;
