insert into public.content_versions (item_id, version, payload) values ('b1-is-spoken', 1, '{"id":"b1-is-spoken","version":1,"level":"B1","primarySkill":"grammar","secondarySkills":[],"difficulty":2,"type":"cloze","category":"sentence-completion","prompt":"English ___ in many countries.","options":[{"id":"a","text":"is spoken"},{"id":"b","text":"speaks","feedback":{"en":"Languages don''t speak; people speak them. We need the passive.","he":"שפה לא מדברת — אנשים מדברים אותה. צריך סביל."},"errorCategory":"passive"},{"id":"c","text":"is speaking"},{"id":"d","text":"spoke"}],"acceptedAnswers":["a"],"grading":{"mode":"option"},"explanation":{"en":"Present Simple passive: am/is/are + past participle.","he":"סביל בהווה פשוט: am/is/are + צורת עבר שלישית."},"tags":{"vocabulary":[],"grammar":["passive-present"],"bagrut":[]},"modes":["word-battle","grammar-race","practice","placement","adventure"],"reviewStatus":"ai-drafted"}'::jsonb) on conflict (item_id, version) do nothing;
