insert into public.content_versions (item_id, version, payload) values ('b1-who-lives', 1, '{"id":"b1-who-lives","version":1,"level":"B1","primarySkill":"grammar","secondarySkills":[],"difficulty":2,"type":"cloze","category":"sentence-completion","prompt":"The woman ___ lives next door is a doctor.","options":[{"id":"a","text":"who"},{"id":"b","text":"which","feedback":{"en":"''Which'' is for things and animals, not people.","he":"which משמש לחפצים ובעלי חיים, לא לאנשים."},"errorCategory":"relative-clause"},{"id":"c","text":"what"},{"id":"d","text":"whose"}],"acceptedAnswers":["a"],"grading":{"mode":"option"},"explanation":{"en":"Use ''who'' (or ''that'') to describe people in a relative clause.","he":"משתמשים ב-who (או that) כדי לתאר אנשים במשפט זיקה."},"tags":{"vocabulary":[],"grammar":["relative-clauses-defining"],"bagrut":[]},"modes":["word-battle","grammar-race","practice","placement","adventure"],"reviewStatus":"ai-drafted"}'::jsonb) on conflict (item_id, version) do nothing;
insert into public.content_items (id, current_version, level, primary_skill, category, item_type, modes, tags, review_status, is_ranked_only) values ('b1-although-cold', 1, 'B1', 'grammar', 'connector', 'cloze', array['word-battle','grammar-race','practice','placement','adventure']::text[], '{"vocabulary":["although"],"grammar":["connectors-contrast"],"bagrut":[]}'::jsonb, 'ai-drafted', false) on conflict (id) do update set current_version = excluded.current_version, level = excluded.level, tags = excluded.tags, review_status = excluded.review_status;
insert into public.content_versions (item_id, version, payload) values ('b1-although-cold', 1, '{"id":"b1-although-cold","version":1,"level":"B1","primarySkill":"grammar","secondarySkills":[],"difficulty":3,"type":"cloze","category":"connector","prompt":"___ it was cold, we went swimming.","options":[{"id":"a","text":"Although"},{"id":"b","text":"Because","feedback":{"en":"Swimming is surprising when it''s cold, so we need contrast, not a reason.","he":"לשחות בקור זה מפתיע — צריך ניגוד, לא סיבה."},"errorCategory":"connector-logic"},{"id":"c","text":"Despite","feedback":{"en":"''Despite'' is followed by a noun or -ing, not a full clause: Despite the cold...","he":"אחרי despite בא שם עצם או ing, לא משפט מלא."},"errorCategory":"connector-logic"},{"id":"d","text":"So"}],"acceptedAnswers":["a"],"grading":{"mode":"option"},"explanation":{"en":"''Although'' + clause shows a surprising contrast between two facts.","he":"although + משפט מבטא ניגוד מפתיע בין שתי עובדות."},"example":"Although she was tired, she finished the race.","tags":{"vocabulary":["although"],"grammar":["connectors-contrast"],"bagrut":[]},"modes":["word-battle","grammar-race","practice","placement","adventure"],"reviewStatus":"ai-drafted"}'::jsonb) on conflict (item_id, version) do nothing;
insert into public.content_items (id, current_version, level, primary_skill, category, item_type, modes, tags, review_status, is_ranked_only) values ('b1-however-hotel', 1, 'B1', 'grammar', 'connector', 'cloze', array['word-battle','grammar-race','practice','placement','adventure']::text[], '{"vocabulary":["however"],"grammar":["connectors-contrast"],"bagrut":[]}'::jsonb, 'ai-drafted', false) on conflict (id) do update set current_version = excluded.current_version, level = excluded.level, tags = excluded.tags, review_status = excluded.review_status;
insert into public.content_versions (item_id, version, payload) values ('b1-however-hotel', 1, '{"id":"b1-however-hotel","version":1,"level":"B1","primarySkill":"grammar","secondarySkills":[],"difficulty":3,"type":"cloze","category":"connector","prompt":"The hotel was expensive. ___, the service was excellent.","options":[{"id":"a","text":"However"},{"id":"b","text":"Therefore","feedback":{"en":"''Therefore'' introduces a result. Excellent service is not a result of the price here.","he":"therefore מציג תוצאה, וזה לא המצב כאן."},"errorCategory":"connector-logic"},{"id":"c","text":"Because"},{"id":"d","text":"Unless"}],"acceptedAnswers":["a"],"grading":{"mode":"option"},"explanation":{"en":"''However'' at the start of a sentence introduces a contrast with the previous sentence.","he":"however בתחילת משפט מציג ניגוד למשפט הקודם."},"tags":{"vocabulary":["however"],"grammar":["connectors-contrast"],"bagrut":[]},"modes":["word-battle","grammar-race","practice","placement","adventure"],"reviewStatus":"ai-drafted"}'::jsonb) on conflict (item_id, version) do nothing;
