insert into public.content_versions (item_id, version, payload) values ('b1-forward-seeing', 1, '{"id":"b1-forward-seeing","version":1,"level":"B1","primarySkill":"grammar","secondarySkills":[],"difficulty":3,"type":"cloze","category":"sentence-completion","prompt":"I''m looking forward to ___ you.","options":[{"id":"a","text":"seeing"},{"id":"b","text":"see","feedback":{"en":"In ''look forward to'', ''to'' is a preposition, so it is followed by -ing.","he":"ב-look forward to המילה to היא מילת יחס, ולכן אחריה בא ing."},"errorCategory":"other"},{"id":"c","text":"saw"},{"id":"d","text":"to see"}],"acceptedAnswers":["a"],"grading":{"mode":"option"},"explanation":{"en":"''Look forward to'' + verb-ing.","he":"look forward to + פועל עם ing."},"tags":{"vocabulary":[],"grammar":["gerund-after-preposition"],"bagrut":[]},"modes":["word-battle","grammar-race","practice","placement","adventure"],"reviewStatus":"ai-drafted"}'::jsonb) on conflict (item_id, version) do nothing;
