insert into public.content_versions (item_id, version, payload) values ('b1-ran-out', 1, '{"id":"b1-ran-out","version":1,"level":"B1","primarySkill":"vocabulary","secondarySkills":[],"difficulty":2,"type":"cloze","category":"phrasal-verb","prompt":"We ran ___ of milk, so I went to the shop.","options":[{"id":"a","text":"out"},{"id":"b","text":"off"},{"id":"c","text":"over"},{"id":"d","text":"away"}],"acceptedAnswers":["a"],"grading":{"mode":"option"},"explanation":{"en":"''Run out of'' something = have none left.","he":"run out of = שנגמר לנו משהו."},"tags":{"vocabulary":["run out of"],"grammar":[],"bagrut":[]},"modes":["word-battle","practice","placement","adventure"],"reviewStatus":"ai-drafted"}'::jsonb) on conflict (item_id, version) do nothing;
