insert into public.content_versions (item_id, version, payload) values ('b1-look-after', 1, '{"id":"b1-look-after","version":1,"level":"B1","primarySkill":"vocabulary","secondarySkills":[],"difficulty":2,"type":"cloze","category":"phrasal-verb","prompt":"Can you look ___ my cat while I''m on holiday?","options":[{"id":"a","text":"after"},{"id":"b","text":"for","feedback":{"en":"''Look for'' means to search for something.","he":"look for פירושו לחפש."},"errorCategory":"phrasal-verb"},{"id":"c","text":"up","feedback":{"en":"''Look up'' means to search for information, e.g. in a dictionary.","he":"look up פירושו לחפש מידע, למשל במילון."},"errorCategory":"phrasal-verb"},{"id":"d","text":"into"}],"acceptedAnswers":["a"],"grading":{"mode":"option"},"explanation":{"en":"''Look after'' = take care of.","he":"look after = לטפל, לשמור על."},"tags":{"vocabulary":["look after"],"grammar":[],"bagrut":[]},"modes":["word-battle","practice","placement","adventure"],"reviewStatus":"ai-drafted"}'::jsonb) on conflict (item_id, version) do nothing;
