insert into public.content_versions (item_id, version, payload) values ('b1-make-decision', 1, '{"id":"b1-make-decision","version":1,"level":"B1","primarySkill":"vocabulary","secondarySkills":[],"difficulty":2,"type":"cloze","category":"collocation","prompt":"I''m going to ___ a decision tonight.","options":[{"id":"a","text":"make"},{"id":"b","text":"do","feedback":{"en":"We say ''make a decision'', not ''do a decision''.","he":"אומרים make a decision ולא do a decision."},"errorCategory":"collocation"},{"id":"c","text":"put"},{"id":"d","text":"bring"}],"acceptedAnswers":["a"],"grading":{"mode":"option"},"explanation":{"en":"Collocation: make a decision (also: make a mistake, make progress).","he":"צירוף קבוע: make a decision (וגם make a mistake, make progress)."},"tags":{"vocabulary":["make a decision"],"grammar":[],"bagrut":[]},"modes":["word-battle","practice","placement","adventure"],"reviewStatus":"ai-drafted"}'::jsonb) on conflict (item_id, version) do nothing;
