insert into public.content_versions (item_id, version, payload) values ('b1-syn-reliable', 1, '{"id":"b1-syn-reliable","version":1,"level":"B1","primarySkill":"vocabulary","secondarySkills":[],"difficulty":3,"type":"multiple-choice","category":"synonym","prompt":"Which word is closest in meaning to ''reliable''?","options":[{"id":"a","text":"dependable"},{"id":"b","text":"careless"},{"id":"c","text":"expensive"},{"id":"d","text":"ordinary"}],"acceptedAnswers":["a"],"grading":{"mode":"option"},"explanation":{"en":"''Reliable'' and ''dependable'' both describe someone or something you can trust to do what is expected.","he":"reliable ו-dependable מתארים מישהו או משהו שאפשר לסמוך עליו."},"tags":{"vocabulary":["reliable","dependable"],"grammar":[],"bagrut":[]},"modes":["word-battle","practice","placement","adventure"],"reviewStatus":"ai-drafted"}'::jsonb) on conflict (item_id, version) do nothing;
