insert into public.content_versions (item_id, version, payload) values ('b1-opp-increase', 1, '{"id":"b1-opp-increase","version":1,"level":"B1","primarySkill":"vocabulary","secondarySkills":[],"difficulty":2,"type":"cloze","category":"antonym","prompt":"The opposite of ''increase'' is ___.","options":[{"id":"a","text":"decrease"},{"id":"b","text":"improve","feedback":{"en":"''Improve'' means to get better, not smaller.","he":"improve פירושו להשתפר, לא לקטון."},"errorCategory":"word-meaning"},{"id":"c","text":"include"},{"id":"d","text":"expand"}],"acceptedAnswers":["a"],"grading":{"mode":"option"},"explanation":{"en":"''Increase'' = go up; ''decrease'' = go down.","he":"increase = לעלות, לגדול; decrease = לרדת, לקטון."},"tags":{"vocabulary":["increase","decrease"],"grammar":[],"bagrut":[]},"modes":["word-battle","practice","placement","adventure"],"reviewStatus":"ai-drafted"}'::jsonb) on conflict (item_id, version) do nothing;
