insert into public.content_versions (item_id, version, payload) values ('b1-delayed', 1, '{"id":"b1-delayed","version":1,"level":"B1","primarySkill":"vocabulary","secondarySkills":[],"difficulty":3,"type":"cloze","category":"contextual-vocabulary","prompt":"The flight was ___ because of the storm, so we waited at the airport for five hours.","options":[{"id":"a","text":"delayed"},{"id":"b","text":"boarded"},{"id":"c","text":"landed"},{"id":"d","text":"booked"}],"acceptedAnswers":["a"],"grading":{"mode":"option"},"explanation":{"en":"Waiting for five hours tells us the flight left late: it was ''delayed''.","he":"ההמתנה של חמש שעות מראה שהטיסה יצאה באיחור: delayed."},"tags":{"vocabulary":["delayed","flight"],"grammar":[],"bagrut":[]},"modes":["word-battle","practice","placement","adventure"],"reviewStatus":"ai-drafted"}'::jsonb) on conflict (item_id, version) do nothing;
