insert into public.content_versions (item_id, version, payload) values ('b1-used-to', 1, '{"id":"b1-used-to","version":1,"level":"B1","primarySkill":"grammar","secondarySkills":[],"difficulty":3,"type":"cloze","category":"sentence-completion","prompt":"When I was a child, I ___ climb trees.","options":[{"id":"a","text":"used to"},{"id":"b","text":"use to"},{"id":"c","text":"was used to","feedback":{"en":"''Be used to'' means ''be accustomed to'' and is followed by -ing.","he":"be used to פירושו להיות רגיל למשהו, ואחריו בא ing."},"errorCategory":"other"},{"id":"d","text":"am used to"}],"acceptedAnswers":["a"],"grading":{"mode":"option"},"explanation":{"en":"''Used to'' + base verb describes past habits that are no longer true.","he":"used to + פועל בסיס מתאר הרגלים בעבר שכבר אינם נכונים."},"tags":{"vocabulary":[],"grammar":["used-to"],"bagrut":[]},"modes":["word-battle","grammar-race","practice","placement","adventure"],"reviewStatus":"ai-drafted"}'::jsonb) on conflict (item_id, version) do nothing;
insert into public.content_items (id, current_version, level, primary_skill, category, item_type, modes, tags, review_status, is_ranked_only) values ('b1-if-had-time', 1, 'B1', 'grammar', 'sentence-completion', 'cloze', array['word-battle','grammar-race','practice','placement','adventure']::text[], '{"vocabulary":[],"grammar":["second-conditional"],"bagrut":[]}'::jsonb, 'ai-drafted', false) on conflict (id) do update set current_version = excluded.current_version, level = excluded.level, tags = excluded.tags, review_status = excluded.review_status;
insert into public.content_versions (item_id, version, payload) values ('b1-if-had-time', 1, '{"id":"b1-if-had-time","version":1,"level":"B1","primarySkill":"grammar","secondarySkills":[],"difficulty":3,"type":"cloze","category":"sentence-completion","prompt":"If I ___ more time, I would learn Japanese.","options":[{"id":"a","text":"had"},{"id":"b","text":"have","feedback":{"en":"With ''would'' in the result, the if-clause uses the past (second conditional).","he":"כש-would בתוצאה, בחלק של if משתמשים בעבר."},"errorCategory":"conditional"},{"id":"c","text":"would have","feedback":{"en":"Don''t use ''would'' in the if-clause.","he":"לא משתמשים ב-would בחלק של if."},"errorCategory":"conditional"},{"id":"d","text":"will have"}],"acceptedAnswers":["a"],"grading":{"mode":"option"},"explanation":{"en":"Second conditional: If + Past Simple, would + base verb — for imaginary or unlikely situations.","he":"משפט תנאי שני: If + עבר פשוט, would + פועל בסיס — למצבים דמיוניים."},"tags":{"vocabulary":[],"grammar":["second-conditional"],"bagrut":[]},"modes":["word-battle","grammar-race","practice","placement","adventure"],"reviewStatus":"ai-drafted"}'::jsonb) on conflict (item_id, version) do nothing;
insert into public.content_items (id, current_version, level, primary_skill, category, item_type, modes, tags, review_status, is_ranked_only) values ('b1-asked-where', 1, 'B1', 'grammar', 'grammar-correction', 'error-correction', array['word-battle','grammar-race','practice','placement','adventure']::text[], '{"vocabulary":[],"grammar":["reported-questions"],"bagrut":[]}'::jsonb, 'ai-drafted', false) on conflict (id) do update set current_version = excluded.current_version, level = excluded.level, tags = excluded.tags, review_status = excluded.review_status;
insert into public.content_versions (item_id, version, payload) values ('b1-asked-where', 1, '{"id":"b1-asked-where","version":1,"level":"B1","primarySkill":"grammar","secondarySkills":[],"difficulty":4,"type":"error-correction","category":"grammar-correction","prompt":"Which sentence is correct?","options":[{"id":"a","text":"He asked me where I lived."},{"id":"b","text":"He asked me where did I live.","feedback":{"en":"Reported questions use normal statement word order, without ''did''.","he":"בשאלה מדווחת משתמשים בסדר מילים של משפט רגיל, בלי did."},"errorCategory":"word-order"},{"id":"c","text":"He asked me where do I live."},{"id":"d","text":"He asked me where I lived?","feedback":{"en":"A reported question is a statement, so it ends with a full stop.","he":"שאלה מדווחת היא משפט חיווי ולכן מסתיימת בנקודה."},"errorCategory":"other"}],"acceptedAnswers":["a"],"grading":{"mode":"option"},"explanation":{"en":"In reported questions, the subject comes before the verb and there is no question mark.","he":"בשאלות מדווחות הנושא בא לפני הפועל ואין סימן שאלה."},"tags":{"vocabulary":[],"grammar":["reported-questions"],"bagrut":[]},"modes":["word-battle","grammar-race","practice","placement","adventure"],"reviewStatus":"ai-drafted"}'::jsonb) on conflict (item_id, version) do nothing;
