insert into public.content_versions (item_id, version, payload) values ('b1-honestly', 1, '{"id":"b1-honestly","version":1,"level":"B1","primarySkill":"grammar","secondarySkills":[],"difficulty":3,"type":"cloze","category":"sentence-completion","prompt":"She spoke very ___ about her experience.","options":[{"id":"a","text":"honestly"},{"id":"b","text":"honest","feedback":{"en":"We need an adverb to describe how she spoke.","he":"צריך תואר פועל כדי לתאר איך היא דיברה."},"errorCategory":"other"},{"id":"c","text":"honesty"},{"id":"d","text":"honestness"}],"acceptedAnswers":["a"],"grading":{"mode":"option"},"explanation":{"en":"Adverbs (often adjective + -ly) describe verbs: speak honestly.","he":"תואר פועל (לרוב תואר + ly) מתאר פועל: speak honestly."},"tags":{"vocabulary":[],"grammar":["adverbs-of-manner"],"bagrut":[]},"modes":["word-battle","grammar-race","practice","placement","adventure"],"reviewStatus":"ai-drafted"}'::jsonb) on conflict (item_id, version) do nothing;
insert into public.content_items (id, current_version, level, primary_skill, category, item_type, modes, tags, review_status, is_ranked_only) values ('b1-daniel-raincoat', 1, 'B1', 'reading', 'reading-inference', 'multiple-choice', array['word-battle','practice','placement','adventure','english-detective']::text[], '{"vocabulary":["infer"],"grammar":[],"bagrut":[]}'::jsonb, 'ai-drafted', false) on conflict (id) do update set current_version = excluded.current_version, level = excluded.level, tags = excluded.tags, review_status = excluded.review_status;
insert into public.content_versions (item_id, version, payload) values ('b1-daniel-raincoat', 1, '{"id":"b1-daniel-raincoat","version":1,"level":"B1","primarySkill":"reading","secondarySkills":[],"difficulty":3,"type":"multiple-choice","category":"reading-inference","prompt":"What can we infer about Daniel?","context":"Daniel checked the weather app three times before leaving. He packed a raincoat, took it out, and then packed it again.","options":[{"id":"a","text":"He was not sure whether it would rain."},{"id":"b","text":"He loves his raincoat."},{"id":"c","text":"He didn''t have a weather app."},{"id":"d","text":"He was going to the beach."}],"acceptedAnswers":["a"],"grading":{"mode":"option"},"explanation":{"en":"Checking the app many times and changing his mind about the raincoat shows he was uncertain about the weather.","he":"הבדיקה החוזרת של האפליקציה והשינוי בהחלטה לגבי מעיל הגשם מראים שהוא לא היה בטוח לגבי מזג האוויר."},"tags":{"vocabulary":["infer"],"grammar":[],"bagrut":[]},"modes":["word-battle","practice","placement","adventure","english-detective"],"reviewStatus":"ai-drafted"}'::jsonb) on conflict (item_id, version) do nothing;
insert into public.content_items (id, current_version, level, primary_skill, category, item_type, modes, tags, review_status, is_ranked_only) values ('b1-too-hot', 1, 'B1', 'grammar', 'sentence-completion', 'cloze', array['word-battle','grammar-race','practice','placement','adventure']::text[], '{"vocabulary":[],"grammar":["too-enough"],"bagrut":[]}'::jsonb, 'ai-drafted', false) on conflict (id) do update set current_version = excluded.current_version, level = excluded.level, tags = excluded.tags, review_status = excluded.review_status;
insert into public.content_versions (item_id, version, payload) values ('b1-too-hot', 1, '{"id":"b1-too-hot","version":1,"level":"B1","primarySkill":"grammar","secondarySkills":[],"difficulty":2,"type":"cloze","category":"sentence-completion","prompt":"This coffee is ___ hot to drink.","options":[{"id":"a","text":"too"},{"id":"b","text":"enough","feedback":{"en":"''Enough'' comes after an adjective (hot enough) and means ''sufficiently''.","he":"enough בא אחרי תואר ופירושו \"מספיק\"."},"errorCategory":"word-order"},{"id":"c","text":"such"},{"id":"d","text":"a lot"}],"acceptedAnswers":["a"],"grading":{"mode":"option"},"explanation":{"en":"''Too'' + adjective + to-infinitive means ''more than is good or possible''.","he":"too + תואר + to פירושו \"יותר מדי\"."},"tags":{"vocabulary":[],"grammar":["too-enough"],"bagrut":[]},"modes":["word-battle","grammar-race","practice","placement","adventure"],"reviewStatus":"ai-drafted"}'::jsonb) on conflict (item_id, version) do nothing;
insert into public.content_items (id, current_version, level, primary_skill, category, item_type, modes, tags, review_status, is_ranked_only) values ('b2-would-have-caught', 1, 'B2', 'grammar', 'sentence-completion', 'cloze', array['word-battle','grammar-race','practice','placement','adventure']::text[], '{"vocabulary":[],"grammar":["third-conditional"],"bagrut":[]}'::jsonb, 'ai-drafted', false) on conflict (id) do update set current_version = excluded.current_version, level = excluded.level, tags = excluded.tags, review_status = excluded.review_status;
insert into public.content_versions (item_id, version, payload) values ('b2-would-have-caught', 1, '{"id":"b2-would-have-caught","version":1,"level":"B2","primarySkill":"grammar","secondarySkills":[],"difficulty":3,"type":"cloze","category":"sentence-completion","prompt":"If we had left earlier, we ___ the train.","options":[{"id":"a","text":"would have caught"},{"id":"b","text":"would catch","feedback":{"en":"The situation is in the past, so the result needs ''would have'' + past participle.","he":"המצב בעבר, ולכן בתוצאה צריך would have + צורה שלישית."},"errorCategory":"conditional"},{"id":"c","text":"will have caught"},{"id":"d","text":"had caught"}],"acceptedAnswers":["a"],"grading":{"mode":"option"},"explanation":{"en":"Third conditional: If + Past Perfect, would have + past participle — for imaginary past situations.","he":"משפט תנאי שלישי: If + Past Perfect, would have + צורה שלישית — למצבים דמיוניים בעבר."},"tags":{"vocabulary":[],"grammar":["third-conditional"],"bagrut":[]},"modes":["word-battle","grammar-race","practice","placement","adventure"],"reviewStatus":"ai-drafted"}'::jsonb) on conflict (item_id, version) do nothing;
