insert into public.content_versions (item_id, version, payload) values ('b2-has-been-closed', 1, '{"id":"b2-has-been-closed","version":1,"level":"B2","primarySkill":"grammar","secondarySkills":[],"difficulty":3,"type":"cloze","category":"sentence-completion","prompt":"The bridge ___ since last year.","options":[{"id":"a","text":"has been closed"},{"id":"b","text":"was closed","feedback":{"en":"''Since'' needs the Present Perfect.","he":"since דורש Present Perfect."},"errorCategory":"tense"},{"id":"c","text":"is closed"},{"id":"d","text":"closed"}],"acceptedAnswers":["a"],"grading":{"mode":"option"},"explanation":{"en":"Present Perfect passive: has/have been + past participle.","he":"סביל ב-Present Perfect: has/have been + צורה שלישית."},"tags":{"vocabulary":[],"grammar":["passive-present-perfect"],"bagrut":[]},"modes":["word-battle","grammar-race","practice","placement","adventure"],"reviewStatus":"ai-drafted"}'::jsonb) on conflict (item_id, version) do nothing;
insert into public.content_items (id, current_version, level, primary_skill, category, item_type, modes, tags, review_status, is_ranked_only) values ('b2-wish-knew', 1, 'B2', 'grammar', 'sentence-completion', 'cloze', array['word-battle','grammar-race','practice','placement','adventure']::text[], '{"vocabulary":[],"grammar":["wish"],"bagrut":[]}'::jsonb, 'ai-drafted', false) on conflict (id) do update set current_version = excluded.current_version, level = excluded.level, tags = excluded.tags, review_status = excluded.review_status;
insert into public.content_versions (item_id, version, payload) values ('b2-wish-knew', 1, '{"id":"b2-wish-knew","version":1,"level":"B2","primarySkill":"grammar","secondarySkills":[],"difficulty":3,"type":"cloze","category":"sentence-completion","prompt":"I wish I ___ how to fix this.","options":[{"id":"a","text":"knew"},{"id":"b","text":"know","feedback":{"en":"After ''wish'' for a present situation, use the past.","he":"אחרי wish למצב בהווה משתמשים בעבר."},"errorCategory":"tense"},{"id":"c","text":"would know"},{"id":"d","text":"have known"}],"acceptedAnswers":["a"],"grading":{"mode":"option"},"explanation":{"en":"''Wish'' + Past Simple expresses a wish about the present.","he":"wish + עבר פשוט מבטא משאלה לגבי ההווה."},"tags":{"vocabulary":[],"grammar":["wish"],"bagrut":[]},"modes":["word-battle","grammar-race","practice","placement","adventure"],"reviewStatus":"ai-drafted"}'::jsonb) on conflict (item_id, version) do nothing;
insert into public.content_items (id, current_version, level, primary_skill, category, item_type, modes, tags, review_status, is_ranked_only) values ('b2-despite-traffic', 1, 'B2', 'grammar', 'connector', 'cloze', array['word-battle','grammar-race','practice','placement','adventure']::text[], '{"vocabulary":["despite"],"grammar":["connectors-contrast"],"bagrut":[]}'::jsonb, 'ai-drafted', false) on conflict (id) do update set current_version = excluded.current_version, level = excluded.level, tags = excluded.tags, review_status = excluded.review_status;
insert into public.content_versions (item_id, version, payload) values ('b2-despite-traffic', 1, '{"id":"b2-despite-traffic","version":1,"level":"B2","primarySkill":"grammar","secondarySkills":[],"difficulty":3,"type":"cloze","category":"connector","prompt":"___ the heavy traffic, she arrived on time.","options":[{"id":"a","text":"Despite"},{"id":"b","text":"Although","feedback":{"en":"''Although'' needs a full clause: Although the traffic was heavy...","he":"although דורש משפט מלא."},"errorCategory":"connector-logic"},{"id":"c","text":"Because of","feedback":{"en":"Traffic would make her late, so we need contrast, not a reason.","he":"פקקים היו גורמים לאיחור — צריך ניגוד ולא סיבה."},"errorCategory":"connector-logic"},{"id":"d","text":"However"}],"acceptedAnswers":["a"],"grading":{"mode":"option"},"explanation":{"en":"''Despite'' / ''In spite of'' + noun or -ing shows contrast.","he":"despite / in spite of + שם עצם או ing מבטא ניגוד."},"tags":{"vocabulary":["despite"],"grammar":["connectors-contrast"],"bagrut":[]},"modes":["word-battle","grammar-race","practice","placement","adventure"],"reviewStatus":"ai-drafted"}'::jsonb) on conflict (item_id, version) do nothing;
