insert into public.content_versions (item_id, version, payload) values ('b2-whereas', 1, '{"id":"b2-whereas","version":1,"level":"B2","primarySkill":"grammar","secondarySkills":[],"difficulty":3,"type":"cloze","category":"connector","prompt":"My sister loves crowded cities, ___ I prefer quiet villages.","options":[{"id":"a","text":"whereas"},{"id":"b","text":"unless"},{"id":"c","text":"therefore","feedback":{"en":"''Therefore'' introduces a result, not a comparison.","he":"therefore מציג תוצאה ולא השוואה."},"errorCategory":"connector-logic"},{"id":"d","text":"despite"}],"acceptedAnswers":["a"],"grading":{"mode":"option"},"explanation":{"en":"''Whereas'' compares two different facts.","he":"whereas משווה בין שתי עובדות שונות."},"tags":{"vocabulary":["whereas"],"grammar":["connectors-contrast"],"bagrut":[]},"modes":["word-battle","grammar-race","practice","placement","adventure"],"reviewStatus":"ai-drafted"}'::jsonb) on conflict (item_id, version) do nothing;
