insert into public.content_versions (item_id, version, payload) values ('b2-put-off', 1, '{"id":"b2-put-off","version":1,"level":"B2","primarySkill":"vocabulary","secondarySkills":[],"difficulty":3,"type":"cloze","category":"phrasal-verb","prompt":"The meeting was ___ until next week because the manager was ill.","options":[{"id":"a","text":"put off"},{"id":"b","text":"put up","feedback":{"en":"''Put up'' means to build, or to let someone stay with you.","he":"put up פירושו לבנות או לארח מישהו."},"errorCategory":"phrasal-verb"},{"id":"c","text":"put on"},{"id":"d","text":"put out"}],"acceptedAnswers":["a"],"grading":{"mode":"option"},"explanation":{"en":"''Put off'' = postpone.","he":"put off = לדחות."},"tags":{"vocabulary":["put off","postpone"],"grammar":[],"bagrut":[]},"modes":["word-battle","practice","placement","adventure"],"reviewStatus":"ai-drafted"}'::jsonb) on conflict (item_id, version) do nothing;
