insert into public.content_versions (item_id, version, payload) values ('b2-put-up-with', 1, '{"id":"b2-put-up-with","version":1,"level":"B2","primarySkill":"vocabulary","secondarySkills":[],"difficulty":4,"type":"cloze","category":"phrasal-verb","prompt":"I can''t ___ with his rude comments anymore.","options":[{"id":"a","text":"put up"},{"id":"b","text":"take up"},{"id":"c","text":"make up"},{"id":"d","text":"bring up"}],"acceptedAnswers":["a"],"grading":{"mode":"option"},"explanation":{"en":"''Put up with'' = tolerate.","he":"put up with = לסבול, להשלים עם."},"tags":{"vocabulary":["put up with","tolerate"],"grammar":[],"bagrut":[]},"modes":["word-battle","practice","placement","adventure"],"reviewStatus":"ai-drafted"}'::jsonb) on conflict (item_id, version) do nothing;
