insert into public.content_versions (item_id, version, payload) values ('b2-impact', 1, '{"id":"b2-impact","version":1,"level":"B2","primarySkill":"vocabulary","secondarySkills":[],"difficulty":3,"type":"cloze","category":"collocation","prompt":"The new policy had a significant ___ on small businesses.","options":[{"id":"a","text":"impact"},{"id":"b","text":"affect","feedback":{"en":"''Affect'' is usually a verb. The noun here is ''impact'' (or ''effect'').","he":"affect הוא בדרך כלל פועל. כאן צריך שם עצם."},"errorCategory":"collocation"},{"id":"c","text":"cause"},{"id":"d","text":"reason"}],"acceptedAnswers":["a"],"grading":{"mode":"option"},"explanation":{"en":"Collocation: have an impact on something.","he":"צירוף: have an impact on — להשפיע על."},"tags":{"vocabulary":["impact"],"grammar":[],"bagrut":[]},"modes":["word-battle","practice","placement","adventure"],"reviewStatus":"ai-drafted"}'::jsonb) on conflict (item_id, version) do nothing;
