insert into public.content_versions (item_id, version, payload) values ('b2-syn-reluctant', 1, '{"id":"b2-syn-reluctant","version":1,"level":"B2","primarySkill":"vocabulary","secondarySkills":[],"difficulty":3,"type":"multiple-choice","category":"synonym","prompt":"Which word is closest in meaning to ''reluctant''?","options":[{"id":"a","text":"unwilling"},{"id":"b","text":"eager","feedback":{"en":"''Eager'' is the opposite: very keen to do something.","he":"eager הוא ההפך: להוט."},"errorCategory":"opposite-meaning"},{"id":"c","text":"curious"},{"id":"d","text":"relieved"}],"acceptedAnswers":["a"],"grading":{"mode":"option"},"explanation":{"en":"''Reluctant'' means not wanting to do something.","he":"reluctant פירושו מסויג, לא רוצה לעשות משהו."},"tags":{"vocabulary":["reluctant","unwilling"],"grammar":[],"bagrut":[]},"modes":["word-battle","practice","placement","adventure"],"reviewStatus":"ai-drafted"}'::jsonb) on conflict (item_id, version) do nothing;
