insert into public.content_versions (item_id, version, payload) values ('b2-opp-scarce', 1, '{"id":"b2-opp-scarce","version":1,"level":"B2","primarySkill":"vocabulary","secondarySkills":[],"difficulty":4,"type":"cloze","category":"antonym","prompt":"The opposite of ''scarce'' is ___.","options":[{"id":"a","text":"plentiful"},{"id":"b","text":"rare","feedback":{"en":"''Rare'' is a synonym of ''scarce'', not its opposite.","he":"rare היא מילה נרדפת ל-scarce, לא הפכית."},"errorCategory":"false-synonym"},{"id":"c","text":"valuable"},{"id":"d","text":"tiny"}],"acceptedAnswers":["a"],"grading":{"mode":"option"},"explanation":{"en":"''Scarce'' = there is not enough; ''plentiful'' = there is a lot.","he":"scarce = נדיר, מועט; plentiful = בשפע."},"tags":{"vocabulary":["scarce","plentiful"],"grammar":[],"bagrut":[]},"modes":["word-battle","practice","placement","adventure"],"reviewStatus":"ai-drafted"}'::jsonb) on conflict (item_id, version) do nothing;
