insert into public.content_versions (item_id, version, payload) values ('b2-confirmed', 1, '{"id":"b2-confirmed","version":1,"level":"B2","primarySkill":"vocabulary","secondarySkills":[],"difficulty":3,"type":"cloze","category":"contextual-vocabulary","prompt":"The scientist''s findings were ___: other researchers repeated the experiment and got the same results.","options":[{"id":"a","text":"confirmed"},{"id":"b","text":"ignored"},{"id":"c","text":"invented"},{"id":"d","text":"hidden"}],"acceptedAnswers":["a"],"grading":{"mode":"option"},"explanation":{"en":"Getting the same results in repeated experiments ''confirms'' the findings.","he":"קבלת אותן תוצאות בניסויים חוזרים מאששת (confirms) את הממצאים."},"tags":{"vocabulary":["confirm","findings"],"grammar":[],"bagrut":[]},"modes":["word-battle","practice","placement","adventure"],"reviewStatus":"ai-drafted"}'::jsonb) on conflict (item_id, version) do nothing;
