insert into public.content_versions (item_id, version, payload) values ('b2-nondefining-who', 1, '{"id":"b2-nondefining-who","version":1,"level":"B2","primarySkill":"grammar","secondarySkills":[],"difficulty":4,"type":"cloze","category":"sentence-completion","prompt":"My grandfather, ___ was born in Morocco, speaks four languages.","options":[{"id":"a","text":"who"},{"id":"b","text":"that","feedback":{"en":"''That'' cannot be used in non-defining relative clauses (with commas).","he":"אי אפשר להשתמש ב-that במשפט זיקה עם פסיקים."},"errorCategory":"relative-clause"},{"id":"c","text":"which"},{"id":"d","text":"whom"}],"acceptedAnswers":["a"],"grading":{"mode":"option"},"explanation":{"en":"Non-defining relative clauses add extra information between commas and use ''who'' or ''which'', never ''that''.","he":"משפט זיקה לא מגדיר (בין פסיקים) משתמש ב-who או which, ולעולם לא ב-that."},"tags":{"vocabulary":[],"grammar":["relative-clauses-non-defining"],"bagrut":[]},"modes":["word-battle","grammar-race","practice","placement","adventure"],"reviewStatus":"ai-drafted"}'::jsonb) on conflict (item_id, version) do nothing;
