insert into public.content_versions (item_id, version, payload) values ('b2-must-be-asleep', 1, '{"id":"b2-must-be-asleep","version":1,"level":"B2","primarySkill":"grammar","secondarySkills":[],"difficulty":4,"type":"cloze","category":"sentence-completion","prompt":"He isn''t answering the door. He ___ be asleep.","options":[{"id":"a","text":"must"},{"id":"b","text":"mustn''t","feedback":{"en":"''Mustn''t'' expresses prohibition, not deduction.","he":"mustn''t מבטא איסור, לא הסקה."},"errorCategory":"modal"},{"id":"c","text":"needn''t"},{"id":"d","text":"would rather"}],"acceptedAnswers":["a"],"grading":{"mode":"option"},"explanation":{"en":"''Must'' + base verb expresses a confident deduction about the present.","he":"must + פועל בסיס מבטא הסקה בטוחה לגבי ההווה."},"tags":{"vocabulary":[],"grammar":["modals-deduction"],"bagrut":[]},"modes":["word-battle","grammar-race","practice","placement","adventure"],"reviewStatus":"ai-drafted"}'::jsonb) on conflict (item_id, version) do nothing;
