insert into public.content_versions (item_id, version, payload) values ('b2-had-repaired', 1, '{"id":"b2-had-repaired","version":1,"level":"B2","primarySkill":"grammar","secondarySkills":[],"difficulty":3,"type":"cloze","category":"sentence-completion","prompt":"I had my car ___ yesterday.","options":[{"id":"a","text":"repaired"},{"id":"b","text":"repair"},{"id":"c","text":"repairing"},{"id":"d","text":"to repair"}],"acceptedAnswers":["a"],"grading":{"mode":"option"},"explanation":{"en":"Causative: have + object + past participle = someone else did it for you.","he":"מבנה גורם: have + מושא + צורה שלישית = מישהו אחר עשה את זה בשבילך."},"tags":{"vocabulary":[],"grammar":["causative-have"],"bagrut":[]},"modes":["word-battle","grammar-race","practice","placement","adventure"],"reviewStatus":"ai-drafted"}'::jsonb) on conflict (item_id, version) do nothing;
insert into public.content_items (id, current_version, level, primary_skill, category, item_type, modes, tags, review_status, is_ranked_only) values ('b2-denied-taking', 1, 'B2', 'grammar', 'sentence-completion', 'cloze', array['word-battle','grammar-race','practice','placement','adventure']::text[], '{"vocabulary":[],"grammar":["verb-patterns-gerund"],"bagrut":[]}'::jsonb, 'ai-drafted', false) on conflict (id) do update set current_version = excluded.current_version, level = excluded.level, tags = excluded.tags, review_status = excluded.review_status;
insert into public.content_versions (item_id, version, payload) values ('b2-denied-taking', 1, '{"id":"b2-denied-taking","version":1,"level":"B2","primarySkill":"grammar","secondarySkills":[],"difficulty":3,"type":"cloze","category":"sentence-completion","prompt":"She denied ___ the money.","options":[{"id":"a","text":"taking"},{"id":"b","text":"to take","feedback":{"en":"''Deny'' is followed by -ing, not by ''to''.","he":"אחרי deny בא ing ולא to."},"errorCategory":"other"},{"id":"c","text":"take"},{"id":"d","text":"taken"}],"acceptedAnswers":["a"],"grading":{"mode":"option"},"explanation":{"en":"Some verbs (deny, avoid, admit, enjoy) are followed by -ing.","he":"אחרי פעלים מסוימים (deny, avoid, admit, enjoy) בא פועל עם ing."},"tags":{"vocabulary":[],"grammar":["verb-patterns-gerund"],"bagrut":[]},"modes":["word-battle","grammar-race","practice","placement","adventure"],"reviewStatus":"ai-drafted"}'::jsonb) on conflict (item_id, version) do nothing;
insert into public.content_items (id, current_version, level, primary_skill, category, item_type, modes, tags, review_status, is_ranked_only) values ('b2-said-would', 1, 'B2', 'grammar', 'sentence-completion', 'cloze', array['word-battle','grammar-race','practice','placement','adventure']::text[], '{"vocabulary":[],"grammar":["reported-speech"],"bagrut":[]}'::jsonb, 'ai-drafted', false) on conflict (id) do update set current_version = excluded.current_version, level = excluded.level, tags = excluded.tags, review_status = excluded.review_status;
insert into public.content_versions (item_id, version, payload) values ('b2-said-would', 1, '{"id":"b2-said-would","version":1,"level":"B2","primarySkill":"grammar","secondarySkills":[],"difficulty":3,"type":"cloze","category":"sentence-completion","prompt":"He said he ___ help me the next day.","options":[{"id":"a","text":"would"},{"id":"b","text":"will","feedback":{"en":"In reported speech after ''said'', ''will'' usually changes to ''would''.","he":"בדיבור עקיף אחרי said, will הופך בדרך כלל ל-would."},"errorCategory":"tense"},{"id":"c","text":"shall"},{"id":"d","text":"does"}],"acceptedAnswers":["a"],"grading":{"mode":"option"},"explanation":{"en":"Reported speech: ''will'' becomes ''would'', and ''tomorrow'' becomes ''the next day''.","he":"בדיבור עקיף will הופך ל-would, ו-tomorrow הופך ל-the next day."},"tags":{"vocabulary":[],"grammar":["reported-speech"],"bagrut":[]},"modes":["word-battle","grammar-race","practice","placement","adventure"],"reviewStatus":"ai-drafted"}'::jsonb) on conflict (item_id, version) do nothing;
insert into public.content_items (id, current_version, level, primary_skill, category, item_type, modes, tags, review_status, is_ranked_only) values ('b2-construction', 1, 'B2', 'grammar', 'sentence-completion', 'cloze', array['word-battle','grammar-race','practice','placement','adventure']::text[], '{"vocabulary":[],"grammar":["word-formation"],"bagrut":[]}'::jsonb, 'ai-drafted', false) on conflict (id) do update set current_version = excluded.current_version, level = excluded.level, tags = excluded.tags, review_status = excluded.review_status;
insert into public.content_versions (item_id, version, payload) values ('b2-construction', 1, '{"id":"b2-construction","version":1,"level":"B2","primarySkill":"grammar","secondarySkills":[],"difficulty":3,"type":"cloze","category":"sentence-completion","prompt":"The ___ of the new hospital will take two years.","options":[{"id":"a","text":"construction"},{"id":"b","text":"construct","feedback":{"en":"After ''the'' we need a noun.","he":"אחרי the צריך שם עצם."},"errorCategory":"other"},{"id":"c","text":"constructive"},{"id":"d","text":"constructed"}],"acceptedAnswers":["a"],"grading":{"mode":"option"},"explanation":{"en":"Word formation: construct (verb) → construction (noun) → constructive (adjective).","he":"גזירת מילים: construct (פועל) ← construction (שם עצם) ← constructive (תואר)."},"tags":{"vocabulary":[],"grammar":["word-formation"],"bagrut":[]},"modes":["word-battle","grammar-race","practice","placement","adventure"],"reviewStatus":"ai-drafted"}'::jsonb) on conflict (item_id, version) do nothing;
insert into public.content_items (id, current_version, level, primary_skill, category, item_type, modes, tags, review_status, is_ranked_only) values ('b2-factories', 1, 'B2', 'reading', 'reading-inference', 'multiple-choice', array['word-battle','practice','placement','adventure','english-detective']::text[], '{"vocabulary":["justify"],"grammar":[],"bagrut":[]}'::jsonb, 'ai-drafted', false) on conflict (id) do update set current_version = excluded.current_version, level = excluded.level, tags = excluded.tags, review_status = excluded.review_status;
insert into public.content_versions (item_id, version, payload) values ('b2-factories', 1, '{"id":"b2-factories","version":1,"level":"B2","primarySkill":"reading","secondarySkills":[],"difficulty":4,"type":"multiple-choice","category":"reading-inference","prompt":"What does the representatives'' comment suggest?","context":"Although the company reported record profits, it announced that it would close two factories. Workers'' representatives called the decision ''impossible to justify''.","options":[{"id":"a","text":"They think the closures are unfair, given the high profits."},{"id":"b","text":"They agree that the company needs to save money."},{"id":"c","text":"They believe the profits were reported incorrectly."},{"id":"d","text":"They want to work in the new factories."}],"acceptedAnswers":["a"],"grading":{"mode":"option"},"explanation":{"en":"''Impossible to justify'', together with ''Although ... record profits'', shows they see no good reason for the closures.","he":"הביטוי impossible to justify יחד עם although ... record profits מראה שלדעתם אין הצדקה לסגירה."},"tags":{"vocabulary":["justify"],"grammar":[],"bagrut":[]},"modes":["word-battle","practice","placement","adventure","english-detective"],"reviewStatus":"ai-drafted"}'::jsonb) on conflict (item_id, version) do nothing;
insert into public.content_items (id, current_version, level, primary_skill, category, item_type, modes, tags, review_status, is_ranked_only) values ('b2-had-started', 1, 'B2', 'grammar', 'sentence-completion', 'cloze', array['word-battle','grammar-race','practice','placement','adventure']::text[], '{"vocabulary":[],"grammar":["past-perfect"],"bagrut":[]}'::jsonb, 'ai-drafted', false) on conflict (id) do update set current_version = excluded.current_version, level = excluded.level, tags = excluded.tags, review_status = excluded.review_status;
insert into public.content_versions (item_id, version, payload) values ('b2-had-started', 1, '{"id":"b2-had-started","version":1,"level":"B2","primarySkill":"grammar","secondarySkills":[],"difficulty":3,"type":"cloze","category":"sentence-completion","prompt":"By the time we arrived, the film ___.","options":[{"id":"a","text":"had already started"},{"id":"b","text":"already started","feedback":{"en":"We need the Past Perfect for the earlier of two past actions.","he":"לפעולה המוקדמת מבין שתי פעולות בעבר צריך Past Perfect."},"errorCategory":"tense"},{"id":"c","text":"has already started"},{"id":"d","text":"was already starting"}],"acceptedAnswers":["a"],"grading":{"mode":"option"},"explanation":{"en":"Past Perfect (had + past participle) shows an action finished before another past moment.","he":"Past Perfect מראה פעולה שהסתיימה לפני רגע אחר בעבר."},"tags":{"vocabulary":[],"grammar":["past-perfect"],"bagrut":[]},"modes":["word-battle","grammar-race","practice","placement","adventure"],"reviewStatus":"ai-drafted"}'::jsonb) on conflict (item_id, version) do nothing;
insert into public.content_items (id, current_version, level, primary_skill, category, item_type, modes, tags, review_status, is_ranked_only) values ('c1-not-only-was-he', 1, 'C1', 'grammar', 'sentence-completion', 'cloze', array['word-battle','grammar-race','practice','placement','adventure']::text[], '{"vocabulary":[],"grammar":["inversion"],"bagrut":[]}'::jsonb, 'ai-drafted', false) on conflict (id) do update set current_version = excluded.current_version, level = excluded.level, tags = excluded.tags, review_status = excluded.review_status;
insert into public.content_versions (item_id, version, payload) values ('c1-not-only-was-he', 1, '{"id":"c1-not-only-was-he","version":1,"level":"C1","primarySkill":"grammar","secondarySkills":[],"difficulty":3,"type":"cloze","category":"sentence-completion","prompt":"Not only ___ late, but he also forgot the tickets.","options":[{"id":"a","text":"was he"},{"id":"b","text":"he was","feedback":{"en":"After a negative adverbial like ''Not only'' at the start, we invert subject and auxiliary.","he":"אחרי ביטוי שלילי בתחילת משפט, כמו Not only, הופכים את סדר הנושא ופועל העזר."},"errorCategory":"word-order"},{"id":"c","text":"did he be"},{"id":"d","text":"he is"}],"acceptedAnswers":["a"],"grading":{"mode":"option"},"explanation":{"en":"Inversion after ''Not only'': Not only + auxiliary + subject.","he":"היפוך אחרי Not only: פועל עזר + נושא."},"tags":{"vocabulary":[],"grammar":["inversion"],"bagrut":[]},"modes":["word-battle","grammar-race","practice","placement","adventure"],"reviewStatus":"ai-drafted"}'::jsonb) on conflict (item_id, version) do nothing;
insert into public.content_items (id, current_version, level, primary_skill, category, item_type, modes, tags, review_status, is_ranked_only) values ('c1-rarely-have-i', 1, 'C1', 'grammar', 'sentence-completion', 'cloze', array['word-battle','grammar-race','practice','placement','adventure']::text[], '{"vocabulary":[],"grammar":["inversion"],"bagrut":[]}'::jsonb, 'ai-drafted', false) on conflict (id) do update set current_version = excluded.current_version, level = excluded.level, tags = excluded.tags, review_status = excluded.review_status;
insert into public.content_versions (item_id, version, payload) values ('c1-rarely-have-i', 1, '{"id":"c1-rarely-have-i","version":1,"level":"C1","primarySkill":"grammar","secondarySkills":[],"difficulty":3,"type":"cloze","category":"sentence-completion","prompt":"Rarely ___ such a breathtaking performance.","options":[{"id":"a","text":"have I seen"},{"id":"b","text":"I have seen","feedback":{"en":"''Rarely'' at the start requires inversion.","he":"Rarely בתחילת משפט דורש היפוך."},"errorCategory":"word-order"},{"id":"c","text":"I saw"},{"id":"d","text":"did I saw"}],"acceptedAnswers":["a"],"grading":{"mode":"option"},"explanation":{"en":"Negative or restrictive adverbs (rarely, seldom, never) at the start trigger inversion.","he":"תארים שליליים או מגבילים בתחילת משפט (rarely, seldom, never) גורמים להיפוך."},"tags":{"vocabulary":[],"grammar":["inversion"],"bagrut":[]},"modes":["word-battle","grammar-race","practice","placement","adventure"],"reviewStatus":"ai-drafted"}'::jsonb) on conflict (item_id, version) do nothing;
insert into public.content_items (id, current_version, level, primary_skill, category, item_type, modes, tags, review_status, is_ranked_only) values ('c1-mixed-would-be', 1, 'C1', 'grammar', 'sentence-completion', 'cloze', array['word-battle','grammar-race','practice','placement','adventure']::text[], '{"vocabulary":[],"grammar":["mixed-conditional"],"bagrut":[]}'::jsonb, 'ai-drafted', false) on conflict (id) do update set current_version = excluded.current_version, level = excluded.level, tags = excluded.tags, review_status = excluded.review_status;
insert into public.content_versions (item_id, version, payload) values ('c1-mixed-would-be', 1, '{"id":"c1-mixed-would-be","version":1,"level":"C1","primarySkill":"grammar","secondarySkills":[],"difficulty":4,"type":"cloze","category":"sentence-completion","prompt":"If I had studied medicine, I ___ a doctor now.","options":[{"id":"a","text":"would be"},{"id":"b","text":"would have been","feedback":{"en":"''Now'' shows a present result, so use ''would'' + base verb.","he":"now מראה תוצאה בהווה, ולכן would + פועל בסיס."},"errorCategory":"conditional"},{"id":"c","text":"will be"},{"id":"d","text":"had been"}],"acceptedAnswers":["a"],"grading":{"mode":"option"},"explanation":{"en":"Mixed conditional: a past condition (Past Perfect) with a present result (would + base verb).","he":"תנאי מעורב: תנאי בעבר (Past Perfect) ותוצאה בהווה (would + פועל בסיס)."},"tags":{"vocabulary":[],"grammar":["mixed-conditional"],"bagrut":[]},"modes":["word-battle","grammar-race","practice","placement","adventure"],"reviewStatus":"ai-drafted"}'::jsonb) on conflict (item_id, version) do nothing;
insert into public.content_items (id, current_version, level, primary_skill, category, item_type, modes, tags, review_status, is_ranked_only) values ('c1-impasse', 1, 'C1', 'vocabulary', 'contextual-vocabulary', 'cloze', array['word-battle','practice','placement','adventure']::text[], '{"vocabulary":["impasse","compromise"],"grammar":[],"bagrut":[]}'::jsonb, 'ai-drafted', false) on conflict (id) do update set current_version = excluded.current_version, level = excluded.level, tags = excluded.tags, review_status = excluded.review_status;
insert into public.content_versions (item_id, version, payload) values ('c1-impasse', 1, '{"id":"c1-impasse","version":1,"level":"C1","primarySkill":"vocabulary","secondarySkills":[],"difficulty":3,"type":"cloze","category":"contextual-vocabulary","prompt":"The negotiations reached a(n) ___: neither side was willing to compromise.","options":[{"id":"a","text":"impasse"},{"id":"b","text":"agreement","feedback":{"en":"If neither side compromises, there is no agreement.","he":"אם אף צד לא מתפשר, אין הסכם."},"errorCategory":"word-meaning"},{"id":"c","text":"outcome"},{"id":"d","text":"consensus"}],"acceptedAnswers":["a"],"grading":{"mode":"option"},"explanation":{"en":"An ''impasse'' is a situation where no progress is possible.","he":"impasse הוא מבוי סתום — מצב שבו אין התקדמות."},"tags":{"vocabulary":["impasse","compromise"],"grammar":[],"bagrut":[]},"modes":["word-battle","practice","placement","adventure"],"reviewStatus":"ai-drafted"}'::jsonb) on conflict (item_id, version) do nothing;
insert into public.content_items (id, current_version, level, primary_skill, category, item_type, modes, tags, review_status, is_ranked_only) values ('c1-raised-concerns', 1, 'C1', 'vocabulary', 'collocation', 'cloze', array['word-battle','practice','placement','adventure']::text[], '{"vocabulary":["raise concerns"],"grammar":[],"bagrut":[]}'::jsonb, 'ai-drafted', false) on conflict (id) do update set current_version = excluded.current_version, level = excluded.level, tags = excluded.tags, review_status = excluded.review_status;
insert into public.content_versions (item_id, version, payload) values ('c1-raised-concerns', 1, '{"id":"c1-raised-concerns","version":1,"level":"C1","primarySkill":"vocabulary","secondarySkills":[],"difficulty":3,"type":"cloze","category":"collocation","prompt":"The report ___ serious concerns about safety.","options":[{"id":"a","text":"raised"},{"id":"b","text":"rose","feedback":{"en":"''Rise'' is intransitive (it has no object). ''Raise'' takes an object.","he":"rise הוא פועל עומד (בלי מושא). raise דורש מושא."},"errorCategory":"collocation"},{"id":"c","text":"arose","feedback":{"en":"''Arise'' is intransitive: concerns arose.","he":"arise הוא פועל עומד: concerns arose."},"errorCategory":"collocation"},{"id":"d","text":"lifted"}],"acceptedAnswers":["a"],"grading":{"mode":"option"},"explanation":{"en":"Collocation: raise concerns / questions / doubts.","he":"צירוף: raise concerns — לעורר חששות."},"tags":{"vocabulary":["raise concerns"],"grammar":[],"bagrut":[]},"modes":["word-battle","practice","placement","adventure"],"reviewStatus":"ai-drafted"}'::jsonb) on conflict (item_id, version) do nothing;
insert into public.content_items (id, current_version, level, primary_skill, category, item_type, modes, tags, review_status, is_ranked_only) values ('c1-ubiquitous', 1, 'C1', 'vocabulary', 'synonym', 'multiple-choice', array['word-battle','practice','placement','adventure']::text[], '{"vocabulary":["ubiquitous"],"grammar":[],"bagrut":[]}'::jsonb, 'ai-drafted', false) on conflict (id) do update set current_version = excluded.current_version, level = excluded.level, tags = excluded.tags, review_status = excluded.review_status;
insert into public.content_versions (item_id, version, payload) values ('c1-ubiquitous', 1, '{"id":"c1-ubiquitous","version":1,"level":"C1","primarySkill":"vocabulary","secondarySkills":[],"difficulty":4,"type":"multiple-choice","category":"synonym","prompt":"Which phrase is closest in meaning to ''ubiquitous''?","options":[{"id":"a","text":"found everywhere"},{"id":"b","text":"extremely rare"},{"id":"c","text":"very old"},{"id":"d","text":"easily broken"}],"acceptedAnswers":["a"],"grading":{"mode":"option"},"explanation":{"en":"''Ubiquitous'' means present or found everywhere.","he":"ubiquitous פירושו נמצא בכל מקום."},"tags":{"vocabulary":["ubiquitous"],"grammar":[],"bagrut":[]},"modes":["word-battle","practice","placement","adventure"],"reviewStatus":"ai-drafted"}'::jsonb) on conflict (item_id, version) do nothing;
insert into public.content_items (id, current_version, level, primary_skill, category, item_type, modes, tags, review_status, is_ranked_only) values ('c1-nevertheless', 1, 'C1', 'grammar', 'connector', 'cloze', array['word-battle','grammar-race','practice','placement','adventure']::text[], '{"vocabulary":["nevertheless"],"grammar":["connectors-contrast"],"bagrut":[]}'::jsonb, 'ai-drafted', false) on conflict (id) do update set current_version = excluded.current_version, level = excluded.level, tags = excluded.tags, review_status = excluded.review_status;
insert into public.content_versions (item_id, version, payload) values ('c1-nevertheless', 1, '{"id":"c1-nevertheless","version":1,"level":"C1","primarySkill":"grammar","secondarySkills":[],"difficulty":3,"type":"cloze","category":"connector","prompt":"The evidence was limited; ___, the committee approved the proposal.","options":[{"id":"a","text":"nevertheless"},{"id":"b","text":"consequently","feedback":{"en":"''Consequently'' introduces a result; approval is not a logical result of limited evidence.","he":"consequently מציג תוצאה, אבל אישור אינו תוצאה הגיונית של ראיות מועטות."},"errorCategory":"connector-logic"},{"id":"c","text":"likewise"},{"id":"d","text":"namely"}],"acceptedAnswers":["a"],"grading":{"mode":"option"},"explanation":{"en":"''Nevertheless'' introduces something that happens in spite of what was just said.","he":"nevertheless (למרות זאת) מציג משהו שקורה למרות מה שנאמר."},"tags":{"vocabulary":["nevertheless"],"grammar":["connectors-contrast"],"bagrut":[]},"modes":["word-battle","grammar-race","practice","placement","adventure"],"reviewStatus":"ai-drafted"}'::jsonb) on conflict (item_id, version) do nothing;
insert into public.content_items (id, current_version, level, primary_skill, category, item_type, modes, tags, review_status, is_ranked_only) values ('c1-came-up-with', 1, 'C1', 'vocabulary', 'phrasal-verb', 'cloze', array['word-battle','practice','placement','adventure']::text[], '{"vocabulary":["come up with"],"grammar":[],"bagrut":[]}'::jsonb, 'ai-drafted', false) on conflict (id) do update set current_version = excluded.current_version, level = excluded.level, tags = excluded.tags, review_status = excluded.review_status;
insert into public.content_versions (item_id, version, payload) values ('c1-came-up-with', 1, '{"id":"c1-came-up-with","version":1,"level":"C1","primarySkill":"vocabulary","secondarySkills":[],"difficulty":3,"type":"cloze","category":"phrasal-verb","prompt":"She came ___ with a brilliant solution.","options":[{"id":"a","text":"up"},{"id":"b","text":"across","feedback":{"en":"''Come across'' means to find by chance, and it isn''t followed by ''with''.","he":"come across פירושו למצוא במקרה, ולא בא אחריו with."},"errorCategory":"phrasal-verb"},{"id":"c","text":"down"},{"id":"d","text":"round"}],"acceptedAnswers":["a"],"grading":{"mode":"option"},"explanation":{"en":"''Come up with'' = think of an idea or plan.","he":"come up with = להעלות רעיון, להמציא פתרון."},"tags":{"vocabulary":["come up with"],"grammar":[],"bagrut":[]},"modes":["word-battle","practice","placement","adventure"],"reviewStatus":"ai-drafted"}'::jsonb) on conflict (item_id, version) do nothing;
insert into public.content_items (id, current_version, level, primary_skill, category, item_type, modes, tags, review_status, is_ranked_only) values ('c1-convoluted', 1, 'C1', 'vocabulary', 'contextual-vocabulary', 'cloze', array['word-battle','practice','placement','adventure']::text[], '{"vocabulary":["convoluted"],"grammar":[],"bagrut":[]}'::jsonb, 'ai-drafted', false) on conflict (id) do update set current_version = excluded.current_version, level = excluded.level, tags = excluded.tags, review_status = excluded.review_status;
insert into public.content_versions (item_id, version, payload) values ('c1-convoluted', 1, '{"id":"c1-convoluted","version":1,"level":"C1","primarySkill":"vocabulary","secondarySkills":[],"difficulty":4,"type":"cloze","category":"contextual-vocabulary","prompt":"His explanation was so ___ that nobody could follow it.","options":[{"id":"a","text":"convoluted"},{"id":"b","text":"lucid","feedback":{"en":"''Lucid'' means very clear — the opposite of what the sentence needs.","he":"lucid פירושו ברור מאוד — ההפך ממה שנדרש."},"errorCategory":"opposite-meaning"},{"id":"c","text":"concise"},{"id":"d","text":"straightforward"}],"acceptedAnswers":["a"],"grading":{"mode":"option"},"explanation":{"en":"''Convoluted'' means extremely complicated and hard to follow.","he":"convoluted פירושו מסובך ומפותל."},"tags":{"vocabulary":["convoluted"],"grammar":[],"bagrut":[]},"modes":["word-battle","practice","placement","adventure"],"reviewStatus":"ai-drafted"}'::jsonb) on conflict (item_id, version) do nothing;
insert into public.content_items (id, current_version, level, primary_skill, category, item_type, modes, tags, review_status, is_ranked_only) values ('c1-recommended-take', 1, 'C1', 'grammar', 'sentence-completion', 'cloze', array['word-battle','grammar-race','practice','placement','adventure']::text[], '{"vocabulary":[],"grammar":["subjunctive"],"bagrut":[]}'::jsonb, 'ai-drafted', false) on conflict (id) do update set current_version = excluded.current_version, level = excluded.level, tags = excluded.tags, review_status = excluded.review_status;
insert into public.content_versions (item_id, version, payload) values ('c1-recommended-take', 1, '{"id":"c1-recommended-take","version":1,"level":"C1","primarySkill":"grammar","secondarySkills":[],"difficulty":4,"type":"cloze","category":"sentence-completion","prompt":"The committee recommended that he ___ the position immediately.","options":[{"id":"a","text":"take"},{"id":"b","text":"taking"},{"id":"c","text":"to take"},{"id":"d","text":"will take"}],"acceptedAnswers":["a"],"grading":{"mode":"option"},"explanation":{"en":"After verbs like recommend, insist and suggest + that, formal English uses the base form (the subjunctive), or ''should'' + base form.","he":"אחרי recommend/insist/suggest + that, באנגלית רשמית משתמשים בצורת הבסיס (subjunctive), או should + פועל בסיס."},"tags":{"vocabulary":[],"grammar":["subjunctive"],"bagrut":[]},"modes":["word-battle","grammar-race","practice","placement","adventure"],"reviewStatus":"ai-drafted"}'::jsonb) on conflict (item_id, version) do nothing;
insert into public.content_items (id, current_version, level, primary_skill, category, item_type, modes, tags, review_status, is_ranked_only) values ('c1-what-i-need', 1, 'C1', 'grammar', 'sentence-completion', 'cloze', array['word-battle','grammar-race','practice','placement','adventure']::text[], '{"vocabulary":[],"grammar":["cleft-sentences"],"bagrut":[]}'::jsonb, 'ai-drafted', false) on conflict (id) do update set current_version = excluded.current_version, level = excluded.level, tags = excluded.tags, review_status = excluded.review_status;
insert into public.content_versions (item_id, version, payload) values ('c1-what-i-need', 1, '{"id":"c1-what-i-need","version":1,"level":"C1","primarySkill":"grammar","secondarySkills":[],"difficulty":3,"type":"cloze","category":"sentence-completion","prompt":"___ I need is a long holiday.","options":[{"id":"a","text":"What"},{"id":"b","text":"That","feedback":{"en":"A cleft sentence that emphasises the object begins with ''What'' (= the thing that).","he":"משפט שסע שמדגיש את המושא מתחיל ב-What."},"errorCategory":"other"},{"id":"c","text":"Which"},{"id":"d","text":"It"}],"acceptedAnswers":["a"],"grading":{"mode":"option"},"explanation":{"en":"Cleft sentence: What + clause + is + emphasised part.","he":"משפט שסע: What + משפט + is + החלק המודגש."},"tags":{"vocabulary":[],"grammar":["cleft-sentences"],"bagrut":[]},"modes":["word-battle","grammar-race","practice","placement","adventure"],"reviewStatus":"ai-drafted"}'::jsonb) on conflict (item_id, version) do nothing;
insert into public.content_items (id, current_version, level, primary_skill, category, item_type, modes, tags, review_status, is_ranked_only) values ('c1-temporary-tax', 1, 'C1', 'reading', 'reading-inference', 'multiple-choice', array['word-battle','practice','placement','adventure','english-detective']::text[], '{"vocabulary":["imply","temporary"],"grammar":[],"bagrut":[]}'::jsonb, 'ai-drafted', false) on conflict (id) do update set current_version = excluded.current_version, level = excluded.level, tags = excluded.tags, review_status = excluded.review_status;
insert into public.content_versions (item_id, version, payload) values ('c1-temporary-tax', 1, '{"id":"c1-temporary-tax","version":1,"level":"C1","primarySkill":"reading","secondarySkills":[],"difficulty":4,"type":"multiple-choice","category":"reading-inference","prompt":"What are the critics implying?","context":"The minister described the new tax as ''temporary'', a word that, critics noted, had also been used about the previous tax for over a decade.","options":[{"id":"a","text":"The new tax will probably not be temporary."},{"id":"b","text":"The minister is new to politics."},{"id":"c","text":"The previous tax was never introduced."},{"id":"d","text":"The critics support the new tax."}],"acceptedAnswers":["a"],"grading":{"mode":"option"},"explanation":{"en":"Pointing out that the previous ''temporary'' tax lasted over ten years suggests scepticism about the new promise.","he":"הציון שהמס ה\"זמני\" הקודם נמשך יותר מעשור מרמז על ספקנות לגבי ההבטחה החדשה."},"tags":{"vocabulary":["imply","temporary"],"grammar":[],"bagrut":[]},"modes":["word-battle","practice","placement","adventure","english-detective"],"reviewStatus":"ai-drafted"}'::jsonb) on conflict (item_id, version) do nothing;
insert into public.content_items (id, current_version, level, primary_skill, category, item_type, modes, tags, review_status, is_ranked_only) values ('c1-undermined', 1, 'C1', 'vocabulary', 'contextual-vocabulary', 'cloze', array['word-battle','practice','placement','adventure']::text[], '{"vocabulary":["undermine"],"grammar":[],"bagrut":[]}'::jsonb, 'ai-drafted', false) on conflict (id) do update set current_version = excluded.current_version, level = excluded.level, tags = excluded.tags, review_status = excluded.review_status;
insert into public.content_versions (item_id, version, payload) values ('c1-undermined', 1, '{"id":"c1-undermined","version":1,"level":"C1","primarySkill":"vocabulary","secondarySkills":[],"difficulty":4,"type":"cloze","category":"contextual-vocabulary","prompt":"Her argument was ___ by a lack of reliable data.","options":[{"id":"a","text":"undermined"},{"id":"b","text":"underlined","feedback":{"en":"''Underline'' means to emphasise.","he":"underline פירושו להדגיש."},"errorCategory":"word-meaning"},{"id":"c","text":"underestimated"},{"id":"d","text":"understood"}],"acceptedAnswers":["a"],"grading":{"mode":"option"},"explanation":{"en":"''Undermine'' = weaken gradually.","he":"undermine = לערער, להחליש."},"tags":{"vocabulary":["undermine"],"grammar":[],"bagrut":[]},"modes":["word-battle","practice","placement","adventure"],"reviewStatus":"ai-drafted"}'::jsonb) on conflict (item_id, version) do nothing;
insert into public.content_items (id, current_version, level, primary_skill, category, item_type, modes, tags, review_status, is_ranked_only) values ('c1-having-read', 1, 'C1', 'grammar', 'sentence-completion', 'cloze', array['word-battle','grammar-race','practice','placement','adventure']::text[], '{"vocabulary":[],"grammar":["participle-clauses"],"bagrut":[]}'::jsonb, 'ai-drafted', false) on conflict (id) do update set current_version = excluded.current_version, level = excluded.level, tags = excluded.tags, review_status = excluded.review_status;
insert into public.content_versions (item_id, version, payload) values ('c1-having-read', 1, '{"id":"c1-having-read","version":1,"level":"C1","primarySkill":"grammar","secondarySkills":[],"difficulty":4,"type":"cloze","category":"sentence-completion","prompt":"___ the instructions, he assembled the desk in ten minutes.","options":[{"id":"a","text":"Having read"},{"id":"b","text":"Having been read","feedback":{"en":"This is passive, but he did the reading himself.","he":"זה סביל, אבל הוא זה שקרא."},"errorCategory":"passive"},{"id":"c","text":"Read"},{"id":"d","text":"To have read"}],"acceptedAnswers":["a"],"grading":{"mode":"option"},"explanation":{"en":"Perfect participle clause (Having + past participle) shows an action completed before the main action.","he":"Having + צורה שלישית מראה פעולה שהושלמה לפני הפעולה העיקרית."},"tags":{"vocabulary":[],"grammar":["participle-clauses"],"bagrut":[]},"modes":["word-battle","grammar-race","practice","placement","adventure"],"reviewStatus":"ai-drafted"}'::jsonb) on conflict (item_id, version) do nothing;
insert into public.content_items (id, current_version, level, primary_skill, category, item_type, modes, tags, review_status, is_ranked_only) values ('c1-academic-register', 1, 'C1', 'writing', 'grammar-correction', 'error-correction', array['word-battle','grammar-race','practice','placement','adventure']::text[], '{"vocabulary":[],"grammar":["academic-hedging"],"bagrut":["module-g-writing"]}'::jsonb, 'ai-drafted', false) on conflict (id) do update set current_version = excluded.current_version, level = excluded.level, tags = excluded.tags, review_status = excluded.review_status;
insert into public.content_versions (item_id, version, payload) values ('c1-academic-register', 1, '{"id":"c1-academic-register","version":1,"level":"C1","primarySkill":"writing","secondarySkills":[],"difficulty":3,"type":"error-correction","category":"grammar-correction","prompt":"Which sentence is most appropriate for an academic essay?","options":[{"id":"a","text":"The results suggest that the method may be effective."},{"id":"b","text":"The results totally prove the method is awesome.","feedback":{"en":"''Totally'' and ''awesome'' are informal, and ''prove'' overstates the evidence.","he":"totally ו-awesome אינן רשמיות, ו-prove מגזים בעוצמת הראיות."},"errorCategory":"register"},{"id":"c","text":"Basically, the method kind of works."},{"id":"d","text":"Everyone knows the method works."}],"acceptedAnswers":["a"],"grading":{"mode":"option"},"explanation":{"en":"Academic writing uses formal vocabulary and hedging (suggest, may) to avoid overclaiming.","he":"בכתיבה אקדמית משתמשים באוצר מילים רשמי ובהסתייגות (suggest, may) כדי לא להגזים בטענות."},"tags":{"vocabulary":[],"grammar":["academic-hedging"],"bagrut":["module-g-writing"]},"modes":["word-battle","grammar-race","practice","placement","adventure"],"reviewStatus":"ai-drafted"}'::jsonb) on conflict (item_id, version) do nothing;
insert into public.content_items (id, current_version, level, primary_skill, category, item_type, modes, tags, review_status, is_ranked_only) values ('c2-turgid', 1, 'C2', 'vocabulary', 'contextual-vocabulary', 'cloze', array['word-battle','practice','placement','adventure']::text[], '{"vocabulary":["turgid"],"grammar":[],"bagrut":[]}'::jsonb, 'ai-drafted', false) on conflict (id) do update set current_version = excluded.current_version, level = excluded.level, tags = excluded.tags, review_status = excluded.review_status;
insert into public.content_versions (item_id, version, payload) values ('c2-turgid', 1, '{"id":"c2-turgid","version":1,"level":"C2","primarySkill":"vocabulary","secondarySkills":[],"difficulty":4,"type":"cloze","category":"contextual-vocabulary","prompt":"The author''s ___ prose makes even simple ideas hard to follow.","options":[{"id":"a","text":"turgid"},{"id":"b","text":"lucid","feedback":{"en":"''Lucid'' means clear — the opposite.","he":"lucid פירושו ברור — ההפך."},"errorCategory":"opposite-meaning"},{"id":"c","text":"limpid"},{"id":"d","text":"pithy"}],"acceptedAnswers":["a"],"grading":{"mode":"option"},"explanation":{"en":"''Turgid'' writing is pompous and difficult to read.","he":"turgid מתאר כתיבה מנופחת וקשה לקריאה."},"tags":{"vocabulary":["turgid"],"grammar":[],"bagrut":[]},"modes":["word-battle","practice","placement","adventure"],"reviewStatus":"ai-drafted"}'::jsonb) on conflict (item_id, version) do nothing;
insert into public.content_items (id, current_version, level, primary_skill, category, item_type, modes, tags, review_status, is_ranked_only) values ('c2-fruition', 1, 'C2', 'vocabulary', 'collocation', 'cloze', array['word-battle','practice','placement','adventure']::text[], '{"vocabulary":["fruition"],"grammar":[],"bagrut":[]}'::jsonb, 'ai-drafted', false) on conflict (id) do update set current_version = excluded.current_version, level = excluded.level, tags = excluded.tags, review_status = excluded.review_status;
insert into public.content_versions (item_id, version, payload) values ('c2-fruition', 1, '{"id":"c2-fruition","version":1,"level":"C2","primarySkill":"vocabulary","secondarySkills":[],"difficulty":3,"type":"cloze","category":"collocation","prompt":"After months of negotiation, the deal finally came to ___.","options":[{"id":"a","text":"fruition"},{"id":"b","text":"fruitful"},{"id":"c","text":"fruit"},{"id":"d","text":"fruitless","feedback":{"en":"''Fruitless'' means unsuccessful — and it is an adjective.","he":"fruitless פירושו חסר תועלת, והוא תואר."},"errorCategory":"word-meaning"}],"acceptedAnswers":["a"],"grading":{"mode":"option"},"explanation":{"en":"''Come to fruition'' = be successfully completed.","he":"come to fruition = להתממש, לבוא לידי ביצוע."},"tags":{"vocabulary":["fruition"],"grammar":[],"bagrut":[]},"modes":["word-battle","practice","placement","adventure"],"reviewStatus":"ai-drafted"}'::jsonb) on conflict (item_id, version) do nothing;
insert into public.content_items (id, current_version, level, primary_skill, category, item_type, modes, tags, review_status, is_ranked_only) values ('c2-should-you', 1, 'C2', 'grammar', 'sentence-completion', 'cloze', array['word-battle','grammar-race','practice','placement','adventure']::text[], '{"vocabulary":[],"grammar":["conditional-inversion"],"bagrut":[]}'::jsonb, 'ai-drafted', false) on conflict (id) do update set current_version = excluded.current_version, level = excluded.level, tags = excluded.tags, review_status = excluded.review_status;
insert into public.content_versions (item_id, version, payload) values ('c2-should-you', 1, '{"id":"c2-should-you","version":1,"level":"C2","primarySkill":"grammar","secondarySkills":[],"difficulty":4,"type":"cloze","category":"sentence-completion","prompt":"___ you require further assistance, please contact our office.","options":[{"id":"a","text":"Should"},{"id":"b","text":"Were","feedback":{"en":"''Were'' inversion needs ''to'': Were you to require...","he":"היפוך עם Were דורש to."},"errorCategory":"conditional"},{"id":"c","text":"Would"},{"id":"d","text":"Had"}],"acceptedAnswers":["a"],"grading":{"mode":"option"},"explanation":{"en":"Formal conditional inversion: Should + subject + base verb = If + subject + present.","he":"היפוך תנאי רשמי: Should + נושא + פועל בסיס = If + נושא + הווה."},"tags":{"vocabulary":[],"grammar":["conditional-inversion"],"bagrut":[]},"modes":["word-battle","grammar-race","practice","placement","adventure"],"reviewStatus":"ai-drafted"}'::jsonb) on conflict (item_id, version) do nothing;
insert into public.content_items (id, current_version, level, primary_skill, category, item_type, modes, tags, review_status, is_ranked_only) values ('c2-cast-doubt', 1, 'C2', 'vocabulary', 'collocation', 'cloze', array['word-battle','practice','placement','adventure']::text[], '{"vocabulary":["cast doubt"],"grammar":[],"bagrut":[]}'::jsonb, 'ai-drafted', false) on conflict (id) do update set current_version = excluded.current_version, level = excluded.level, tags = excluded.tags, review_status = excluded.review_status;
insert into public.content_versions (item_id, version, payload) values ('c2-cast-doubt', 1, '{"id":"c2-cast-doubt","version":1,"level":"C2","primarySkill":"vocabulary","secondarySkills":[],"difficulty":3,"type":"cloze","category":"collocation","prompt":"The new evidence ___ doubt on the original verdict.","options":[{"id":"a","text":"cast"},{"id":"b","text":"made"},{"id":"c","text":"put"},{"id":"d","text":"gave"}],"acceptedAnswers":["a"],"grading":{"mode":"option"},"explanation":{"en":"Collocation: cast doubt on something = make it seem less certain.","he":"צירוף: cast doubt on — להטיל ספק ב..."},"tags":{"vocabulary":["cast doubt"],"grammar":[],"bagrut":[]},"modes":["word-battle","practice","placement","adventure"],"reviewStatus":"ai-drafted"}'::jsonb) on conflict (item_id, version) do nothing;
insert into public.content_items (id, current_version, level, primary_skill, category, item_type, modes, tags, review_status, is_ranked_only) values ('c2-disingenuous', 1, 'C2', 'vocabulary', 'contextual-vocabulary', 'cloze', array['word-battle','practice','placement','adventure']::text[], '{"vocabulary":["disingenuous"],"grammar":[],"bagrut":[]}'::jsonb, 'ai-drafted', false) on conflict (id) do update set current_version = excluded.current_version, level = excluded.level, tags = excluded.tags, review_status = excluded.review_status;
insert into public.content_versions (item_id, version, payload) values ('c2-disingenuous', 1, '{"id":"c2-disingenuous","version":1,"level":"C2","primarySkill":"vocabulary","secondarySkills":[],"difficulty":5,"type":"cloze","category":"contextual-vocabulary","prompt":"The CEO''s apology seemed ___, as it came only after the scandal went viral.","options":[{"id":"a","text":"disingenuous"},{"id":"b","text":"ingenious","feedback":{"en":"''Ingenious'' means clever and inventive.","he":"ingenious פירושו מחוכם, יצירתי."},"errorCategory":"word-meaning"},{"id":"c","text":"ingenuous","feedback":{"en":"''Ingenuous'' means innocent and naive.","he":"ingenuous פירושו תמים."},"errorCategory":"word-meaning"},{"id":"d","text":"genuine"}],"acceptedAnswers":["a"],"grading":{"mode":"option"},"explanation":{"en":"''Disingenuous'' means not sincere, pretending to be more honest than one is.","he":"disingenuous פירושו לא כן, מעמיד פנים של כנות."},"tags":{"vocabulary":["disingenuous"],"grammar":[],"bagrut":[]},"modes":["word-battle","practice","placement","adventure"],"reviewStatus":"ai-drafted"}'::jsonb) on conflict (item_id, version) do nothing;
insert into public.content_items (id, current_version, level, primary_skill, category, item_type, modes, tags, review_status, is_ranked_only) values ('c2-notwithstanding', 1, 'C2', 'grammar', 'connector', 'cloze', array['word-battle','grammar-race','practice','placement','adventure']::text[], '{"vocabulary":["notwithstanding"],"grammar":["connectors-contrast"],"bagrut":[]}'::jsonb, 'ai-drafted', false) on conflict (id) do update set current_version = excluded.current_version, level = excluded.level, tags = excluded.tags, review_status = excluded.review_status;
insert into public.content_versions (item_id, version, payload) values ('c2-notwithstanding', 1, '{"id":"c2-notwithstanding","version":1,"level":"C2","primarySkill":"grammar","secondarySkills":[],"difficulty":4,"type":"cloze","category":"connector","prompt":"___ his reputation for caution, the investor made a surprisingly risky bet.","options":[{"id":"a","text":"Notwithstanding"},{"id":"b","text":"Albeit","feedback":{"en":"''Albeit'' is followed by an adjective, adverb or phrase, not a noun phrase like this.","he":"אחרי albeit בא תואר או צירוף, לא צירוף שמני כזה."},"errorCategory":"connector-logic"},{"id":"c","text":"Insofar as"},{"id":"d","text":"Whereby"}],"acceptedAnswers":["a"],"grading":{"mode":"option"},"explanation":{"en":"''Notwithstanding'' (formal) = despite.","he":"notwithstanding (רשמי) = למרות."},"tags":{"vocabulary":["notwithstanding"],"grammar":["connectors-contrast"],"bagrut":[]},"modes":["word-battle","grammar-race","practice","placement","adventure"],"reviewStatus":"ai-drafted"}'::jsonb) on conflict (item_id, version) do nothing;
insert into public.content_items (id, current_version, level, primary_skill, category, item_type, modes, tags, review_status, is_ranked_only) values ('c2-so-severe', 1, 'C2', 'grammar', 'sentence-completion', 'cloze', array['word-battle','grammar-race','practice','placement','adventure']::text[], '{"vocabulary":[],"grammar":["inversion"],"bagrut":[]}'::jsonb, 'ai-drafted', false) on conflict (id) do update set current_version = excluded.current_version, level = excluded.level, tags = excluded.tags, review_status = excluded.review_status;
insert into public.content_versions (item_id, version, payload) values ('c2-so-severe', 1, '{"id":"c2-so-severe","version":1,"level":"C2","primarySkill":"grammar","secondarySkills":[],"difficulty":4,"type":"cloze","category":"sentence-completion","prompt":"So ___ was the storm that the ferry service was suspended.","options":[{"id":"a","text":"severe"},{"id":"b","text":"severely"},{"id":"c","text":"severity"},{"id":"d","text":"severest"}],"acceptedAnswers":["a"],"grading":{"mode":"option"},"explanation":{"en":"Emphatic inversion: So + adjective + verb + subject + that-clause.","he":"היפוך להדגשה: So + תואר + פועל + נושא + that."},"tags":{"vocabulary":[],"grammar":["inversion"],"bagrut":[]},"modes":["word-battle","grammar-race","practice","placement","adventure"],"reviewStatus":"ai-drafted"}'::jsonb) on conflict (item_id, version) do nothing;
insert into public.content_items (id, current_version, level, primary_skill, category, item_type, modes, tags, review_status, is_ranked_only) values ('c2-novel-review', 1, 'C2', 'reading', 'reading-inference', 'multiple-choice', array['word-battle','practice','placement','adventure','english-detective']::text[], '{"vocabulary":["imply"],"grammar":[],"bagrut":[]}'::jsonb, 'ai-drafted', false) on conflict (id) do update set current_version = excluded.current_version, level = excluded.level, tags = excluded.tags, review_status = excluded.review_status;
insert into public.content_versions (item_id, version, payload) values ('c2-novel-review', 1, '{"id":"c2-novel-review","version":1,"level":"C2","primarySkill":"reading","secondarySkills":[],"difficulty":5,"type":"multiple-choice","category":"reading-inference","prompt":"What does the review most likely imply?","context":"The review praised the novel''s ''ambition'', ''scope'' and ''courage'', but did not once mention whether it was enjoyable to read.","options":[{"id":"a","text":"The novel may be impressive but not pleasant to read."},{"id":"b","text":"The reviewer didn''t finish the book."},{"id":"c","text":"The novel is short and simple."},{"id":"d","text":"The reviewer loved every page."}],"acceptedAnswers":["a"],"grading":{"mode":"option"},"explanation":{"en":"Praising only abstract qualities while avoiding the question of enjoyment is a subtle way of suggesting the book is hard going.","he":"שבח רק לתכונות מופשטות והתעלמות מהשאלה אם הספר מהנה רומזים בעדינות שקשה לקרוא אותו."},"tags":{"vocabulary":["imply"],"grammar":[],"bagrut":[]},"modes":["word-battle","practice","placement","adventure","english-detective"],"reviewStatus":"ai-drafted"}'::jsonb) on conflict (item_id, version) do nothing;
insert into public.content_items (id, current_version, level, primary_skill, category, item_type, modes, tags, review_status, is_ranked_only) values ('c2-play-down', 1, 'C2', 'vocabulary', 'phrasal-verb', 'cloze', array['word-battle','practice','placement','adventure']::text[], '{"vocabulary":["play down"],"grammar":[],"bagrut":[]}'::jsonb, 'ai-drafted', false) on conflict (id) do update set current_version = excluded.current_version, level = excluded.level, tags = excluded.tags, review_status = excluded.review_status;
insert into public.content_versions (item_id, version, payload) values ('c2-play-down', 1, '{"id":"c2-play-down","version":1,"level":"C2","primarySkill":"vocabulary","secondarySkills":[],"difficulty":4,"type":"cloze","category":"phrasal-verb","prompt":"The minister tried to ___ the scandal, but journalists kept asking questions.","options":[{"id":"a","text":"play down"},{"id":"b","text":"play up","feedback":{"en":"''Play up'' means to exaggerate or emphasise — the opposite.","he":"play up פירושו להגזים או להבליט — ההפך."},"errorCategory":"opposite-meaning"},{"id":"c","text":"play out"},{"id":"d","text":"play along"}],"acceptedAnswers":["a"],"grading":{"mode":"option"},"explanation":{"en":"''Play down'' = make something seem less important.","he":"play down = להמעיט בחשיבות של משהו."},"tags":{"vocabulary":["play down"],"grammar":[],"bagrut":[]},"modes":["word-battle","practice","placement","adventure"],"reviewStatus":"ai-drafted"}'::jsonb) on conflict (item_id, version) do nothing;
