insert into public.content_versions (item_id, version, payload) values ('sb-a1-green-apples', 1, '{"id":"sb-a1-green-apples","version":1,"level":"A1","primarySkill":"grammar","secondarySkills":["writing"],"difficulty":1,"type":"sentence-build","category":"sentence-building","prompt":"Say that you like green apples.","tiles":["I","like","green","apples"],"acceptedAnswers":["I like green apples."],"grading":{"mode":"token-sequence"},"explanation":{"en":"English word order: subject + verb + object. Adjectives come before the noun.","he":"סדר המילים באנגלית: נושא + פועל + מושא. שם התואר בא לפני שם העצם."},"commonMistakes":[{"sequence":"I like apples green","feedback":{"en":"In English the adjective comes before the noun: green apples.","he":"באנגלית שם התואר בא לפני שם העצם: green apples."},"errorCategory":"word-order"}],"tags":{"vocabulary":[],"grammar":["word-order-svo","adjective-order"],"bagrut":[]},"modes":["sentence-master","practice","adventure"],"reviewStatus":"ai-drafted"}'::jsonb) on conflict (item_id, version) do nothing;
