insert into public.content_versions (item_id, version, payload) values ('sb-b1-never-london', 1, '{"id":"sb-b1-never-london","version":1,"level":"B1","primarySkill":"grammar","secondarySkills":["writing"],"difficulty":2,"type":"sentence-build","category":"sentence-building","prompt":"Say that you have no experience of visiting London.","tiles":["I","have","never","been","to","London"],"acceptedAnswers":["I have never been to London."],"grading":{"mode":"token-sequence"},"explanation":{"en":"''Never'' goes between ''have'' and the past participle.","he":"never בא בין have לבין הצורה השלישית."},"commonMistakes":[{"sequence":"I have been never to London","feedback":{"en":"Put ''never'' before ''been''.","he":"שמים את never לפני been."},"errorCategory":"word-order"},{"sequence":"I never have been to London","feedback":{"en":"''Never'' normally goes after the auxiliary ''have''.","he":"never בא בדרך כלל אחרי פועל העזר have."},"errorCategory":"word-order"}],"tags":{"vocabulary":[],"grammar":["present-perfect-experience"],"bagrut":[]},"modes":["sentence-master","practice","adventure"],"reviewStatus":"ai-drafted"}'::jsonb) on conflict (item_id, version) do nothing;
