insert into public.content_versions (item_id, version, payload) values ('sb-b1-although-late', 1, '{"id":"sb-b1-although-late","version":1,"level":"B1","primarySkill":"grammar","secondarySkills":["writing"],"difficulty":3,"type":"sentence-build","category":"sentence-building","prompt":"Show that she continued even though it was late.","tiles":["Although","it","was","late",",","she","kept","working"],"acceptedAnswers":["Although it was late, she kept working."],"grading":{"mode":"token-sequence"},"explanation":{"en":"''Although'' + clause, then a comma, then the main clause.","he":"although + משפט, פסיק, ואז המשפט העיקרי."},"commonMistakes":[{"sequence":"Although she kept working , it was late","feedback":{"en":"''Although'' must introduce the surprising contrast — the fact that it was late.","he":"although צריך להציג את העובדה המנוגדת — שהיה מאוחר."},"errorCategory":"connector-logic"}],"tags":{"vocabulary":["although"],"grammar":["connectors-contrast"],"bagrut":[]},"modes":["sentence-master","practice","adventure"],"reviewStatus":"ai-drafted"}'::jsonb) on conflict (item_id, version) do nothing;
