insert into public.content_versions (item_id, version, payload) values ('sb-c1-not-only', 1, '{"id":"sb-c1-not-only","version":1,"level":"C1","primarySkill":"grammar","secondarySkills":["writing"],"difficulty":4,"type":"sentence-build","category":"sentence-building","prompt":"Emphasise two advantages of the new train.","tiles":["Not","only","is","it","cheaper",",","but","it","is","also","faster"],"acceptedAnswers":["Not only is it cheaper, but it is also faster."],"grading":{"mode":"token-sequence"},"explanation":{"en":"Inversion after ''Not only'' (is it), followed by ''but ... also''.","he":"היפוך אחרי Not only (is it), ואחריו but ... also."},"commonMistakes":[{"sequence":"Not only it is cheaper , but is it also faster","feedback":{"en":"The inversion belongs in the ''Not only'' clause, not in the ''but'' clause.","he":"ההיפוך שייך לחלק של Not only, לא לחלק של but."},"errorCategory":"word-order"}],"tags":{"vocabulary":[],"grammar":["inversion"],"bagrut":[]},"modes":["sentence-master","practice","adventure"],"reviewStatus":"ai-drafted"}'::jsonb) on conflict (item_id, version) do nothing;
