insert into public.content_versions (item_id, version, payload) values ('rd-cc-elsewhere', 1, '{"id":"rd-cc-elsewhere","version":1,"level":"C1","primarySkill":"inference","secondarySkills":[],"difficulty":3,"type":"multiple-choice","category":"reading-inference","prompt":"What does the writer mean by ''its costs are simply moved elsewhere''?","options":[{"id":"a","text":"Other people pay the price of the convenience."},{"id":"b","text":"Delivery apps are cheaper in other countries."},{"id":"c","text":"Customers pay more than they realise."},{"id":"d","text":"The apps will soon disappear."}],"acceptedAnswers":["a"],"grading":{"mode":"option"},"explanation":{"en":"Paragraph 2 shows riders and restaurants carrying the costs.","he":"פסקה 2 מראה שהשליחים והמסעדות נושאים בעלויות."},"tags":{"vocabulary":[],"grammar":[],"bagrut":["module-g"]},"modes":["practice","bagrut","adventure","english-detective"],"reviewStatus":"ai-drafted","passageId":"p-cost-of-convenience"}'::jsonb) on conflict (item_id, version) do nothing;
