insert into public.content_versions (item_id, version, payload) values ('rd-cc-defenders', 1, '{"id":"rd-cc-defenders","version":1,"level":"C1","primarySkill":"reading","secondarySkills":["inference"],"difficulty":4,"type":"multiple-choice","category":"reading-inference","prompt":"How does the writer treat the defenders'' arguments in paragraph 3?","options":[{"id":"a","text":"Acknowledges them as valid before continuing the argument"},{"id":"b","text":"Rejects them as completely false"},{"id":"c","text":"Ignores them entirely"},{"id":"d","text":"Accepts them as the final conclusion"}],"acceptedAnswers":["a"],"grading":{"mode":"option"},"explanation":{"en":"''These points deserve to be taken seriously'' — the writer concedes before returning to the main claim.","he":"These points deserve to be taken seriously — הכותב מודה בטיעוני הנגד לפני שהוא חוזר לטענתו."},"tags":{"vocabulary":[],"grammar":[],"bagrut":["module-g"]},"modes":["practice","bagrut","adventure","english-detective"],"reviewStatus":"ai-drafted","passageId":"p-cost-of-convenience"}'::jsonb) on conflict (item_id, version) do nothing;
