insert into public.content_versions (item_id, version, payload) values ('rd-cc-position', 1, '{"id":"rd-cc-position","version":1,"level":"C1","primarySkill":"reading","secondarySkills":["inference"],"difficulty":4,"type":"multiple-choice","category":"reading-inference","prompt":"Which statement best summarises the writer''s position?","options":[{"id":"a","text":"Delivery should cost customers more, to reflect its real cost."},{"id":"b","text":"Delivery apps should be banned."},{"id":"c","text":"Riders should work fixed hours."},{"id":"d","text":"Restaurants should stop using delivery apps."}],"acceptedAnswers":["a"],"grading":{"mode":"option"},"explanation":{"en":"The conclusion: ''A modest delivery fee that reflected the true cost... would be considerably more honest.''","he":"המסקנה: דמי משלוח שמשקפים את העלות האמיתית יהיו הוגנים יותר."},"tags":{"vocabulary":[],"grammar":[],"bagrut":["module-g"]},"modes":["practice","bagrut","adventure","english-detective"],"reviewStatus":"ai-drafted","passageId":"p-cost-of-convenience"}'::jsonb) on conflict (item_id, version) do nothing;
