insert into public.content_versions (item_id, version, payload) values ('rd-cc-tone', 1, '{"id":"rd-cc-tone","version":1,"level":"C1","primarySkill":"inference","secondarySkills":[],"difficulty":5,"type":"cloze","category":"reading-inference","prompt":"The phrase ''everyone except the customer'' is used to ___.","options":[{"id":"a","text":"highlight an unfair distribution of costs"},{"id":"b","text":"praise customers for their choices"},{"id":"c","text":"show that customers pay too much"},{"id":"d","text":"suggest that the apps are dishonest"}],"acceptedAnswers":["a"],"grading":{"mode":"option"},"explanation":{"en":"It emphasises, with some irony, that the people who benefit most pay the least.","he":"הביטוי מדגיש, באירוניה מסוימת, שמי שנהנה הכי הרבה משלם הכי מעט."},"tags":{"vocabulary":[],"grammar":[],"bagrut":["module-g"]},"modes":["practice","bagrut","adventure","english-detective"],"reviewStatus":"ai-drafted","passageId":"p-cost-of-convenience"}'::jsonb) on conflict (item_id, version) do nothing;
