insert into public.content_versions (item_id, version, payload) values ('bg-f-lanterns-symbol', 1, '{"id":"bg-f-lanterns-symbol","version":1,"level":"B2","primarySkill":"reading","secondarySkills":["inference"],"difficulty":4,"type":"multiple-choice","category":"reading-inference","prompt":"In the poem, what does the lantern most likely symbolise?","options":[{"id":"a","text":"A promise of return and the care a parent shows"},{"id":"b","text":"The danger of working at night"},{"id":"c","text":"The modernisation of the harbour"},{"id":"d","text":"The father''s fear of the dark"}],"acceptedAnswers":["a"],"grading":{"mode":"option"},"explanation":{"en":"The father explains the light as a sign he is coming home; the speaker later repeats the gesture for his own son.","he":"האב מסביר שהאור הוא סימן לכך שהוא חוזר הביתה; הדובר חוזר על המחווה עבור בנו."},"tags":{"vocabulary":[],"grammar":[],"bagrut":["module-f"]},"modes":["bagrut","practice"],"reviewStatus":"ai-drafted","passageId":"lit-lanterns"}'::jsonb) on conflict (item_id, version) do nothing;
