insert into public.content_versions (item_id, version, payload) values ('bg-f-lanterns-change', 1, '{"id":"bg-f-lanterns-change","version":1,"level":"B2","primarySkill":"inference","secondarySkills":[],"difficulty":4,"type":"multiple-choice","category":"reading-inference","prompt":"How has the speaker''s understanding changed by the last stanza?","options":[{"id":"a","text":"He now understands the lantern from a parent''s point of view."},{"id":"b","text":"He has forgotten why his father hung the lantern."},{"id":"c","text":"He thinks the lantern was unnecessary."},{"id":"d","text":"He wants to work at the harbour."}],"acceptedAnswers":["a"],"grading":{"mode":"option"},"explanation":{"en":"As a child he ''was too young to understand''; as a father he repeats the words ''so you know''.","he":"כילד הוא \"היה צעיר מכדי להבין\"; כאב הוא חוזר על המילים so you know."},"tags":{"vocabulary":[],"grammar":[],"bagrut":["module-f"]},"modes":["bagrut","practice"],"reviewStatus":"ai-drafted","passageId":"lit-lanterns"}'::jsonb) on conflict (item_id, version) do nothing;
