insert into public.content_versions (item_id, version, payload) values ('bg-f-ferry-sailor', 1, '{"id":"bg-f-ferry-sailor","version":1,"level":"B2","primarySkill":"inference","secondarySkills":[],"difficulty":4,"type":"multiple-choice","category":"reading-inference","prompt":"What is the main purpose of the sailor''s story about wanting to be a painter?","options":[{"id":"a","text":"To encourage Noa not to wait for the \"right moment\""},{"id":"b","text":"To explain why he works on the ferry"},{"id":"c","text":"To criticise Noa for being late"},{"id":"d","text":"To show that painting is a bad career"}],"acceptedAnswers":["a"],"grading":{"mode":"option"},"explanation":{"en":"His regret (''I kept waiting for the right moment'') and the line ''The ferry doesn''t wait'' connect directly to Noa''s hidden decision.","he":"החרטה שלו והמשפט The ferry doesn''t wait מתחברים ישירות להחלטה הסודית של נועה."},"tags":{"vocabulary":[],"grammar":[],"bagrut":["module-f"]},"modes":["bagrut","practice"],"reviewStatus":"ai-drafted","passageId":"lit-last-ferry"}'::jsonb) on conflict (item_id, version) do nothing;
