insert into public.content_versions (item_id, version, payload) values ('bg-f-ferry-ending', 1, '{"id":"bg-f-ferry-ending","version":1,"level":"B2","primarySkill":"inference","secondarySkills":[],"difficulty":5,"type":"multiple-choice","category":"reading-inference","prompt":"What does the ending suggest about Noa?","options":[{"id":"a","text":"She has decided to send her application."},{"id":"b","text":"She has decided to study law."},{"id":"c","text":"She is afraid to go home."},{"id":"d","text":"She wants to work on the ferry."}],"acceptedAnswers":["a"],"grading":{"mode":"option"},"explanation":{"en":"Waiting outside the post office all night with the envelope shows determination to send it as soon as possible.","he":"ההמתנה כל הלילה מחוץ לדואר עם המעטפה מראה נחישות לשלוח אותה מוקדם ככל האפשר."},"tags":{"vocabulary":[],"grammar":[],"bagrut":["module-f"]},"modes":["bagrut","practice"],"reviewStatus":"ai-drafted","passageId":"lit-last-ferry"}'::jsonb) on conflict (item_id, version) do nothing;
