insert into public.content_versions (item_id, version, payload) values ('ls-a1-time', 1, '{"id":"ls-a1-time","version":1,"level":"A1","primarySkill":"listening","secondarySkills":[],"difficulty":2,"type":"multiple-choice","category":"listening","prompt":"When does the bus leave?","listen":"The bus to the museum leaves at half past nine.","options":[{"id":"a","text":"9:30"},{"id":"b","text":"9:00"},{"id":"c","text":"9:15"},{"id":"d","text":"10:30"}],"acceptedAnswers":["a"],"grading":{"mode":"option"},"explanation":{"en":"''Half past nine'' means 9:30.","he":"half past nine פירושו תשע וחצי."},"tags":{"vocabulary":["half past"],"grammar":[],"bagrut":[]},"modes":["practice","bagrut","adventure"],"reviewStatus":"ai-drafted"}'::jsonb) on conflict (item_id, version) do nothing;
