insert into public.content_versions (item_id, version, payload) values ('ls-a2-weekend', 1, '{"id":"ls-a2-weekend","version":1,"level":"A2","primarySkill":"listening","secondarySkills":[],"difficulty":2,"type":"multiple-choice","category":"listening","prompt":"Why did the speaker stay at home on Sunday?","listen":"On Saturday I visited my grandmother, and on Sunday I stayed at home because it was raining.","options":[{"id":"a","text":"Because of the rain"},{"id":"b","text":"Because grandmother visited"},{"id":"c","text":"Because they were ill"},{"id":"d","text":"Because it was Saturday"}],"acceptedAnswers":["a"],"grading":{"mode":"option"},"explanation":{"en":"The speaker says ''because it was raining''.","he":"הדובר אומר: because it was raining."},"tags":{"vocabulary":["because","stay"],"grammar":[],"bagrut":[]},"modes":["practice","bagrut","adventure"],"reviewStatus":"ai-drafted"}'::jsonb) on conflict (item_id, version) do nothing;
