insert into public.content_versions (item_id, version, payload) values ('ls-a2-directions', 1, '{"id":"ls-a2-directions","version":1,"level":"A2","primarySkill":"listening","secondarySkills":[],"difficulty":3,"type":"multiple-choice","category":"listening","prompt":"Where is the library?","listen":"Go straight on, turn left at the bank, and the library is on your right, next to the post office.","options":[{"id":"a","text":"On the right, next to the post office"},{"id":"b","text":"On the left, next to the bank"},{"id":"c","text":"Opposite the post office"},{"id":"d","text":"Behind the bank"}],"acceptedAnswers":["a"],"grading":{"mode":"option"},"explanation":{"en":"After turning left at the bank, the library is ''on your right, next to the post office''.","he":"אחרי הפנייה שמאלה ליד הבנק, הספרייה מימין, ליד הדואר."},"tags":{"vocabulary":["next to","turn left"],"grammar":[],"bagrut":[]},"modes":["practice","bagrut","adventure"],"reviewStatus":"ai-drafted"}'::jsonb) on conflict (item_id, version) do nothing;
