insert into public.content_versions (item_id, version, payload) values ('ls-a2-phone', 1, '{"id":"ls-a2-phone","version":1,"level":"A2","primarySkill":"listening","secondarySkills":[],"difficulty":3,"type":"multiple-choice","category":"listening","prompt":"What does Tom want to do?","listen":"Hi Dana, it''s Tom. I''m sorry, I can''t come to the cinema tonight. Can we go tomorrow instead?","options":[{"id":"a","text":"Go to the cinema tomorrow"},{"id":"b","text":"Go to the cinema tonight"},{"id":"c","text":"Cancel the plan completely"},{"id":"d","text":"Meet Dana at home"}],"acceptedAnswers":["a"],"grading":{"mode":"option"},"explanation":{"en":"''Can we go tomorrow instead?'' — he wants to change the day, not cancel.","he":"Can we go tomorrow instead? — הוא רוצה לשנות את היום, לא לבטל."},"tags":{"vocabulary":["instead"],"grammar":[],"bagrut":[]},"modes":["practice","bagrut","adventure"],"reviewStatus":"ai-drafted"}'::jsonb) on conflict (item_id, version) do nothing;
