insert into public.content_versions (item_id, version, payload) values ('ls-b1-announcement', 1, '{"id":"ls-b1-announcement","version":1,"level":"B1","primarySkill":"listening","secondarySkills":[],"difficulty":3,"type":"multiple-choice","category":"listening","prompt":"What has changed?","listen":"Attention, passengers. The 4:15 train to Haifa will now depart from platform six instead of platform two. We apologise for any inconvenience.","options":[{"id":"a","text":"The platform"},{"id":"b","text":"The departure time"},{"id":"c","text":"The destination"},{"id":"d","text":"The price of tickets"}],"acceptedAnswers":["a"],"grading":{"mode":"option"},"explanation":{"en":"The train will depart ''from platform six instead of platform two'' — only the platform changed.","he":"הרכבת תצא מרציף שש במקום מרציף שתיים — רק הרציף השתנה."},"tags":{"vocabulary":["instead of","depart"],"grammar":[],"bagrut":[]},"modes":["practice","bagrut","adventure"],"reviewStatus":"ai-drafted"}'::jsonb) on conflict (item_id, version) do nothing;
