insert into public.content_versions (item_id, version, payload) values ('ls-b1-interview', 1, '{"id":"ls-b1-interview","version":1,"level":"B1","primarySkill":"listening","secondarySkills":[],"difficulty":3,"type":"multiple-choice","category":"listening","prompt":"Why did the speaker leave their last job?","listen":"I really enjoyed my last job, but after three years I felt I wasn''t learning anything new, so I decided to look for a new challenge.","options":[{"id":"a","text":"They wanted to keep learning"},{"id":"b","text":"They did not enjoy it"},{"id":"c","text":"The salary was too low"},{"id":"d","text":"The company closed"}],"acceptedAnswers":["a"],"grading":{"mode":"option"},"explanation":{"en":"''I wasn''t learning anything new, so I decided to look for a new challenge.''","he":"הדובר לא למד יותר דברים חדשים, ולכן חיפש אתגר חדש."},"tags":{"vocabulary":["challenge"],"grammar":[],"bagrut":[]},"modes":["practice","bagrut","adventure"],"reviewStatus":"ai-drafted"}'::jsonb) on conflict (item_id, version) do nothing;
