insert into public.content_versions (item_id, version, payload) values ('ls-b1-weather', 1, '{"id":"ls-b1-weather","version":1,"level":"B1","primarySkill":"listening","secondarySkills":[],"difficulty":2,"type":"multiple-choice","category":"listening","prompt":"What will the evening be like?","listen":"Tomorrow will start cloudy, but the sun should come out by midday. Don''t forget a jacket for the evening, as temperatures will drop.","options":[{"id":"a","text":"Colder"},{"id":"b","text":"Sunny and hot"},{"id":"c","text":"Rainy"},{"id":"d","text":"Cloudy all day"}],"acceptedAnswers":["a"],"grading":{"mode":"option"},"explanation":{"en":"''Temperatures will drop'' in the evening, so it will be colder.","he":"בערב הטמפרטורות ירדו, ולכן יהיה קר יותר."},"tags":{"vocabulary":["drop","temperature"],"grammar":[],"bagrut":[]},"modes":["practice","bagrut","adventure"],"reviewStatus":"ai-drafted"}'::jsonb) on conflict (item_id, version) do nothing;
