insert into public.content_versions (item_id, version, payload) values ('ls-b2-podcast', 1, '{"id":"ls-b2-podcast","version":1,"level":"B2","primarySkill":"listening","secondarySkills":[],"difficulty":4,"type":"multiple-choice","category":"listening","prompt":"What is the speaker''s main point?","listen":"Many people assume that multitasking makes them more productive. In fact, switching between tasks costs time, because the brain needs a moment to refocus every time.","options":[{"id":"a","text":"Multitasking is less efficient than people think"},{"id":"b","text":"Multitasking improves concentration"},{"id":"c","text":"The brain never needs to refocus"},{"id":"d","text":"People should work longer hours"}],"acceptedAnswers":["a"],"grading":{"mode":"option"},"explanation":{"en":"''In fact, switching between tasks costs time'' contradicts the common assumption.","he":"In fact, switching between tasks costs time — סותר את ההנחה הנפוצה."},"tags":{"vocabulary":["assume","in fact"],"grammar":[],"bagrut":[]},"modes":["practice","bagrut","adventure"],"reviewStatus":"ai-drafted"}'::jsonb) on conflict (item_id, version) do nothing;
