insert into public.content_versions (item_id, version, payload) values ('ls-b2-complaint', 1, '{"id":"ls-b2-complaint","version":1,"level":"B2","primarySkill":"listening","secondarySkills":[],"difficulty":4,"type":"multiple-choice","category":"listening","prompt":"What does the caller want?","listen":"I''m calling about the laptop I ordered. It arrived on time, which I appreciate, but the screen was cracked, so I''d like a replacement rather than a refund.","options":[{"id":"a","text":"A new laptop"},{"id":"b","text":"Their money back"},{"id":"c","text":"A faster delivery"},{"id":"d","text":"A discount on a screen"}],"acceptedAnswers":["a"],"grading":{"mode":"option"},"explanation":{"en":"''I''d like a replacement rather than a refund'' — they want a new laptop, not their money.","he":"הם רוצים מחשב חלופי ולא החזר כספי."},"tags":{"vocabulary":["replacement","refund"],"grammar":[],"bagrut":[]},"modes":["practice","bagrut","adventure"],"reviewStatus":"ai-drafted"}'::jsonb) on conflict (item_id, version) do nothing;
