insert into public.content_versions (item_id, version, payload) values ('ls-c1-lecture', 1, '{"id":"ls-c1-lecture","version":1,"level":"C1","primarySkill":"listening","secondarySkills":[],"difficulty":4,"type":"multiple-choice","category":"listening","prompt":"According to the critics, why did prices keep rising?","listen":"While the policy was well intentioned, its critics argue that it addressed the symptoms of the housing crisis rather than its underlying causes, which is why prices continued to climb.","options":[{"id":"a","text":"The policy did not tackle the root causes"},{"id":"b","text":"The policy was badly intentioned"},{"id":"c","text":"There was no housing crisis"},{"id":"d","text":"The policy was never introduced"}],"acceptedAnswers":["a"],"grading":{"mode":"option"},"explanation":{"en":"Critics say it treated ''symptoms … rather than its underlying causes''.","he":"המבקרים טוענים שהמדיניות טיפלה בסימפטומים ולא בגורמים העמוקים."},"tags":{"vocabulary":["underlying","symptom"],"grammar":[],"bagrut":[]},"modes":["practice","bagrut","adventure"],"reviewStatus":"ai-drafted"}'::jsonb) on conflict (item_id, version) do nothing;
