insert into public.content_versions (item_id, version, payload) values ('ls-c1-tone', 1, '{"id":"ls-c1-tone","version":1,"level":"C1","primarySkill":"listening","secondarySkills":[],"difficulty":5,"type":"multiple-choice","category":"listening","prompt":"How does the speaker feel?","listen":"Oh, wonderful. The printer''s broken again, just ten minutes before the presentation. Exactly what I needed today.","options":[{"id":"a","text":"Frustrated, speaking sarcastically"},{"id":"b","text":"Genuinely delighted"},{"id":"c","text":"Calm and indifferent"},{"id":"d","text":"Grateful for the help"}],"acceptedAnswers":["a"],"grading":{"mode":"option"},"explanation":{"en":"''Wonderful'' and ''exactly what I needed'' are sarcastic — the situation is bad.","he":"wonderful ו-exactly what I needed נאמרים בציניות — המצב רע."},"tags":{"vocabulary":["sarcastic"],"grammar":[],"bagrut":[]},"modes":["practice","bagrut","adventure"],"reviewStatus":"ai-drafted"}'::jsonb) on conflict (item_id, version) do nothing;
