insert into public.content_versions (item_id, version, payload) values ('c1-x-wish-would', 1, '{"id":"c1-x-wish-would","version":1,"level":"C1","primarySkill":"grammar","secondarySkills":[],"difficulty":4,"type":"cloze","category":"sentence-completion","prompt":"I wish my neighbours ___ playing loud music at night.","options":[{"id":"a","text":"would stop"},{"id":"b","text":"stop","feedback":{"en":"To complain about other people''s habits, use ''wish + would''.","he":"כדי להתלונן על הרגלים של אחרים משתמשים ב-wish + would."},"errorCategory":"modal"},{"id":"c","text":"will stop"},{"id":"d","text":"stopped to"}],"acceptedAnswers":["a"],"grading":{"mode":"option"},"explanation":{"en":"''Wish + would'' expresses annoyance about someone else''s behaviour.","he":"wish + would מביע רוגז על התנהגות של מישהו אחר."},"tags":{"vocabulary":[],"grammar":["wish"],"bagrut":[]},"modes":["word-battle","grammar-race","practice","placement","adventure"],"reviewStatus":"ai-drafted"}'::jsonb) on conflict (item_id, version) do nothing;
