insert into public.content_versions (item_id, version, payload) values ('c1-x-carry-out', 1, '{"id":"c1-x-carry-out","version":1,"level":"C1","primarySkill":"vocabulary","secondarySkills":[],"difficulty":4,"type":"cloze","category":"phrasal-verb","prompt":"The researchers ___ a series of experiments over two years.","options":[{"id":"a","text":"carried out"},{"id":"b","text":"carried on"},{"id":"c","text":"carried off"},{"id":"d","text":"carried away"}],"acceptedAnswers":["a"],"grading":{"mode":"option"},"explanation":{"en":"''Carry out'' = perform or conduct (research, a plan, an order).","he":"carry out = לבצע (מחקר, תוכנית)."},"tags":{"vocabulary":["carry out"],"grammar":[],"bagrut":[]},"modes":["word-battle","practice","placement","adventure"],"reviewStatus":"ai-drafted"}'::jsonb) on conflict (item_id, version) do nothing;
insert into public.content_items (id, current_version, level, primary_skill, category, item_type, modes, tags, review_status, is_ranked_only) values ('c1-x-fewer', 1, 'C1', 'grammar', 'grammar-correction', 'multiple-choice', array['word-battle','grammar-race','practice','placement','adventure']::text[], '{"vocabulary":[],"grammar":["quantifiers"],"bagrut":[]}'::jsonb, 'ai-drafted', false) on conflict (id) do update set current_version = excluded.current_version, level = excluded.level, tags = excluded.tags, review_status = excluded.review_status;
insert into public.content_versions (item_id, version, payload) values ('c1-x-fewer', 1, '{"id":"c1-x-fewer","version":1,"level":"C1","primarySkill":"grammar","secondarySkills":[],"difficulty":4,"type":"multiple-choice","category":"grammar-correction","prompt":"Which sentence is correct in careful written English?","options":[{"id":"a","text":"There were fewer people at the concert than we had expected."},{"id":"b","text":"There were less people at the concert than we had expected.","feedback":{"en":"With countable plural nouns, careful English uses ''fewer''.","he":"עם שמות ספירים ברבים, באנגלית מוקפדת משתמשים ב-fewer."},"errorCategory":"comparison"},{"id":"c","text":"There were fewer people at the concert that we had expected."},{"id":"d","text":"There were few people at the concert than we had expected."}],"acceptedAnswers":["a"],"grading":{"mode":"option"},"explanation":{"en":"''Fewer'' + countable plural; comparatives take ''than''.","he":"fewer + שם ספיר ברבים; בהשוואה אומרים than."},"tags":{"vocabulary":[],"grammar":["quantifiers"],"bagrut":[]},"modes":["word-battle","grammar-race","practice","placement","adventure"],"reviewStatus":"ai-drafted"}'::jsonb) on conflict (item_id, version) do nothing;
insert into public.content_items (id, current_version, level, primary_skill, category, item_type, modes, tags, review_status, is_ranked_only) values ('c1-x-dwindling', 1, 'C1', 'reading', 'reading-inference', 'multiple-choice', array['word-battle','practice','placement','adventure','english-detective']::text[], '{"vocabulary":["dwindling"],"grammar":[],"bagrut":[]}'::jsonb, 'ai-drafted', false) on conflict (id) do update set current_version = excluded.current_version, level = excluded.level, tags = excluded.tags, review_status = excluded.review_status;
insert into public.content_versions (item_id, version, payload) values ('c1-x-dwindling', 1, '{"id":"c1-x-dwindling","version":1,"level":"C1","primarySkill":"reading","secondarySkills":[],"difficulty":4,"type":"multiple-choice","category":"reading-inference","prompt":"Why has the museum reduced its opening hours?","context":"The museum will now open only from 10:00 to 14:00 on weekdays, a change the director described as ''a necessary response to dwindling attendance''.","options":[{"id":"a","text":"Fewer people have been visiting."},{"id":"b","text":"The building is being renovated."},{"id":"c","text":"Visitor numbers have doubled."},{"id":"d","text":"The director wants longer holidays."}],"acceptedAnswers":["a"],"grading":{"mode":"option"},"explanation":{"en":"''Dwindling attendance'' = the number of visitors is getting smaller.","he":"dwindling attendance = מספר המבקרים הולך וקטן."},"tags":{"vocabulary":["dwindling"],"grammar":[],"bagrut":[]},"modes":["word-battle","practice","placement","adventure","english-detective"],"reviewStatus":"ai-drafted"}'::jsonb) on conflict (item_id, version) do nothing;
