insert into public.content_versions (item_id, version, payload) values ('c2-x-notwithstanding', 1, '{"id":"c2-x-notwithstanding","version":1,"level":"C2","primarySkill":"grammar","secondarySkills":[],"difficulty":5,"type":"cloze","category":"connector","prompt":"The project went ahead, the residents'' objections ___.","options":[{"id":"a","text":"notwithstanding"},{"id":"b","text":"nevertheless"},{"id":"c","text":"whereas"},{"id":"d","text":"thereof"}],"acceptedAnswers":["a"],"grading":{"mode":"option"},"explanation":{"en":"''Notwithstanding'' (formal) = despite; it can follow the noun it refers to.","he":"notwithstanding (רשמי) = למרות; יכול לבוא אחרי שם העצם."},"tags":{"vocabulary":["notwithstanding"],"grammar":[],"bagrut":[]},"modes":["word-battle","grammar-race","practice","placement","adventure"],"reviewStatus":"ai-drafted"}'::jsonb) on conflict (item_id, version) do nothing;
insert into public.content_items (id, current_version, level, primary_skill, category, item_type, modes, tags, review_status, is_ranked_only) values ('c2-x-quintessential', 1, 'C2', 'vocabulary', 'contextual-vocabulary', 'cloze', array['word-battle','practice','placement','adventure']::text[], '{"vocabulary":["quintessential"],"grammar":[],"bagrut":[]}'::jsonb, 'ai-drafted', false) on conflict (id) do update set current_version = excluded.current_version, level = excluded.level, tags = excluded.tags, review_status = excluded.review_status;
insert into public.content_versions (item_id, version, payload) values ('c2-x-quintessential', 1, '{"id":"c2-x-quintessential","version":1,"level":"C2","primarySkill":"vocabulary","secondarySkills":[],"difficulty":5,"type":"cloze","category":"contextual-vocabulary","prompt":"With its red phone boxes and black cabs, the street looked like the ___ London scene.","options":[{"id":"a","text":"quintessential"},{"id":"b","text":"peripheral"},{"id":"c","text":"erroneous"},{"id":"d","text":"clandestine"}],"acceptedAnswers":["a"],"grading":{"mode":"option"},"explanation":{"en":"''Quintessential'' = the most typical example of something.","he":"quintessential = הדוגמה המובהקת והטיפוסית ביותר."},"tags":{"vocabulary":["quintessential"],"grammar":[],"bagrut":[]},"modes":["word-battle","practice","placement","adventure"],"reviewStatus":"ai-drafted"}'::jsonb) on conflict (item_id, version) do nothing;
insert into public.content_items (id, current_version, level, primary_skill, category, item_type, modes, tags, review_status, is_ranked_only) values ('c2-x-so-complex', 1, 'C2', 'grammar', 'sentence-completion', 'cloze', array['word-battle','grammar-race','practice','placement','adventure']::text[], '{"vocabulary":[],"grammar":["inversion"],"bagrut":[]}'::jsonb, 'ai-drafted', false) on conflict (id) do update set current_version = excluded.current_version, level = excluded.level, tags = excluded.tags, review_status = excluded.review_status;
insert into public.content_versions (item_id, version, payload) values ('c2-x-so-complex', 1, '{"id":"c2-x-so-complex","version":1,"level":"C2","primarySkill":"grammar","secondarySkills":[],"difficulty":5,"type":"cloze","category":"sentence-completion","prompt":"So complex ___ that even experts disagreed about its meaning.","options":[{"id":"a","text":"was the poem"},{"id":"b","text":"the poem was","feedback":{"en":"After ''So + adjective'' at the start of a sentence, invert: So complex was the poem…","he":"אחרי So + שם תואר בתחילת המשפט יש היפוך: So complex was the poem…"},"errorCategory":"word-order"},{"id":"c","text":"did the poem"},{"id":"d","text":"the poem did"}],"acceptedAnswers":["a"],"grading":{"mode":"option"},"explanation":{"en":"Fronted ''So + adjective'' + inverted ''be'' + subject, for emphasis.","he":"So + שם תואר בתחילת המשפט + היפוך של be והנושא, להדגשה."},"tags":{"vocabulary":[],"grammar":["inversion"],"bagrut":[]},"modes":["word-battle","grammar-race","practice","placement","adventure"],"reviewStatus":"ai-drafted"}'::jsonb) on conflict (item_id, version) do nothing;
insert into public.content_items (id, current_version, level, primary_skill, category, item_type, modes, tags, review_status, is_ranked_only) values ('c2-x-pore-over', 1, 'C2', 'vocabulary', 'phrasal-verb', 'cloze', array['word-battle','practice','placement','adventure']::text[], '{"vocabulary":["pore over"],"grammar":[],"bagrut":[]}'::jsonb, 'ai-drafted', false) on conflict (id) do update set current_version = excluded.current_version, level = excluded.level, tags = excluded.tags, review_status = excluded.review_status;
insert into public.content_versions (item_id, version, payload) values ('c2-x-pore-over', 1, '{"id":"c2-x-pore-over","version":1,"level":"C2","primarySkill":"vocabulary","secondarySkills":[],"difficulty":5,"type":"cloze","category":"phrasal-verb","prompt":"She spent hours ___ the old maps, looking for clues.","options":[{"id":"a","text":"poring over"},{"id":"b","text":"pouring over","feedback":{"en":"''Pore over'' = study closely; ''pour'' is for liquids.","he":"pore over = לעיין לעומק; pour מתייחס לנוזלים."},"errorCategory":"spelling"},{"id":"c","text":"passing over"},{"id":"d","text":"putting off"}],"acceptedAnswers":["a"],"grading":{"mode":"option"},"explanation":{"en":"''Pore over'' = read or examine something very carefully.","he":"pore over = לעיין במשהו בעיון רב."},"tags":{"vocabulary":["pore over"],"grammar":[],"bagrut":[]},"modes":["word-battle","practice","placement","adventure"],"reviewStatus":"ai-drafted"}'::jsonb) on conflict (item_id, version) do nothing;
insert into public.content_items (id, current_version, level, primary_skill, category, item_type, modes, tags, review_status, is_ranked_only) values ('c2-x-academic-register', 1, 'C2', 'grammar', 'grammar-correction', 'multiple-choice', array['word-battle','grammar-race','practice','placement','adventure']::text[], '{"vocabulary":["hedging"],"grammar":[],"bagrut":[]}'::jsonb, 'ai-drafted', false) on conflict (id) do update set current_version = excluded.current_version, level = excluded.level, tags = excluded.tags, review_status = excluded.review_status;
insert into public.content_versions (item_id, version, payload) values ('c2-x-academic-register', 1, '{"id":"c2-x-academic-register","version":1,"level":"C2","primarySkill":"grammar","secondarySkills":[],"difficulty":5,"type":"multiple-choice","category":"grammar-correction","prompt":"Which sentence is most appropriate in an academic essay?","options":[{"id":"a","text":"The data would appear to suggest a link between sleep and memory."},{"id":"b","text":"The data totally proves that sleep and memory are linked.","feedback":{"en":"Academic writing avoids overclaiming (''proves'') and informal words (''totally'').","he":"בכתיבה אקדמית נמנעים מטענות מוגזמות (proves) וממילים לא רשמיות (totally)."},"errorCategory":"register"},{"id":"c","text":"Sleep and memory? Definitely connected, no doubt."},{"id":"d","text":"Everyone knows that sleep fixes your memory."}],"acceptedAnswers":["a"],"grading":{"mode":"option"},"explanation":{"en":"Hedging (''would appear to suggest'') is typical of cautious academic claims.","he":"הסתייגות (would appear to suggest) אופיינית לטענות אקדמיות זהירות."},"tags":{"vocabulary":["hedging"],"grammar":[],"bagrut":[]},"modes":["word-battle","grammar-race","practice","placement","adventure"],"reviewStatus":"ai-drafted"}'::jsonb) on conflict (item_id, version) do nothing;
insert into public.content_items (id, current_version, level, primary_skill, category, item_type, modes, tags, review_status, is_ranked_only) values ('c2-x-faint-praise', 1, 'C2', 'reading', 'reading-inference', 'multiple-choice', array['word-battle','practice','placement','adventure','english-detective']::text[], '{"vocabulary":["faint praise"],"grammar":[],"bagrut":[]}'::jsonb, 'ai-drafted', false) on conflict (id) do update set current_version = excluded.current_version, level = excluded.level, tags = excluded.tags, review_status = excluded.review_status;
insert into public.content_versions (item_id, version, payload) values ('c2-x-faint-praise', 1, '{"id":"c2-x-faint-praise","version":1,"level":"C2","primarySkill":"reading","secondarySkills":[],"difficulty":5,"type":"multiple-choice","category":"reading-inference","prompt":"What does the letter most likely imply about Mr Adler''s work?","context":"From a reference letter: ''Mr Adler was always punctual, and his handwriting is very neat.''","options":[{"id":"a","text":"The writer has little positive to say about his actual work."},{"id":"b","text":"He was the best employee in the company."},{"id":"c","text":"He was frequently late."},{"id":"d","text":"His handwriting was hard to read."}],"acceptedAnswers":["a"],"grading":{"mode":"option"},"explanation":{"en":"Praising only minor qualities in a reference (''damning with faint praise'') suggests the main work was not impressive.","he":"שבח רק לתכונות שוליות במכתב המלצה מרמז שהעבודה עצמה לא הייתה מרשימה."},"tags":{"vocabulary":["faint praise"],"grammar":[],"bagrut":[]},"modes":["word-battle","practice","placement","adventure","english-detective"],"reviewStatus":"ai-drafted"}'::jsonb) on conflict (item_id, version) do nothing;
